const m = (
  order: number,
  title: string,
  description: string,
  core: string,
  keyPoints: string[],
  steps: string[],
  scenario: string,
  correct: string,
  distractors: string[],
  sourceIds: string[],
): ProcuraduriaModuleBlueprint => ({
  id:`pgn-m${order}`, unitId:`pgn-u${Math.floor(order / 5)}`, order, code:`M${order}`, title, description, core, keyPoints, steps, scenario, correct, distractors, sourceIds, skillIds:[`pgn-skill-${order}`],
})

export const procuraduriaModuleBlueprints: ProcuraduriaModuleBlueprint[] = [
  m(0,'Tu empleo y la Convocatoria 104-2026','Propósito, funciones, requisitos y peso real de cada prueba.','El Profesional Universitario 3PU-15 pertenece al proceso Preventivo–Disciplinario. La convocatoria versión 4 ofrece 100 cargos, no exige experiencia y espera apoyo profesional en instrucción, prevención, intervención, prueba, análisis de información, atención e implementación de sistemas de gestión.',[
    'Conocimientos es eliminatoria, exige 65/100 y pesa 70 %; comportamentales 20 % y antecedentes 10 %.','Las funciones 1, 4 y 5 convierten instrucción, prueba y despachos comisorios en núcleo prioritario.','Tu título de Ingeniería de Sistemas es una puerta de entrada, pero el empleo sigue siendo multidisciplinario y jurídico-operativo.'
  ],['Lee propósito y funciones antes del temario.','Mapea función → conocimiento → norma → habilidad.','Prioriza instrucción, probatorio y preventivo.','Usa tu experticia técnica sin exceder competencia jurídica.'],
  'Te asignan apoyo en un expediente con registros de acceso y una posible alteración de datos.','Ubicar competencia, etapa y pregunta probatoria; después producir análisis técnico trazable sin declarar responsabilidad jurídica.',['Concluir autoría solo porque una cuenta aparece en un log.','Limitarte a explicar qué es un log sin conectarlo con el expediente.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-manual-v9','pgn-concurso-2026']),

  m(1,'Derecho para quien empieza desde cero','Vocabulario mínimo: norma, competencia, acto, expediente, término, recurso y prueba.','El Derecho distribuye potestades, impone límites y organiza procedimientos. Una regla nunca se aplica solo porque “existe”: hay que verificar supuesto, autoridad competente, etapa y efecto jurídico.',[
    'La Constitución es norma superior y marco de derechos y organización estatal.','Competencia es habilitación jurídica; no se reemplaza por buena intención o experiencia.','Expediente es memoria organizada de actuaciones y soportes, no una simple carpeta.'
  ],['Separa hechos de opiniones.','Pregunta quién puede actuar.','Ubica la etapa.','Busca la regla y el soporte que justifican la actuación.'],
  'Una opción cita una norma real pero la aplica una autoridad incompetente.','Descartar la opción porque la corrección del artículo no subsana la falta de competencia.',['Aceptar porque la norma citada es verdadera.','Escoger la alternativa más rápida aunque omita competencia.'],['constitucion','cpaca','ley-1952-2019']),

  m(2,'Método de estudio jurídico Umbral','Aprender Derecho sin memorizar artículos a ciegas.','La preparación útil construye modelos mentales: finalidad, concepto, secuencia, límites, evidencia y excepción. Los números de artículos se consolidan después de comprender el problema que resuelven.',[
    'Familiaridad por relectura no equivale a dominio.','Recuperación activa obliga a reconstruir la regla sin verla.','El cuaderno de errores debe registrar la causa del fallo, no solo la respuesta correcta.'
  ],['Comprende el concepto.','Explícalo con tus palabras.','Resuelve un microcaso.','Verifica en la fuente oficial y corrige el modelo.'],
  'Recuerdas que la indagación dura seis meses, pero no sabes cuándo procede ni cómo termina.','Volver al propósito, condiciones de inicio, término, posibles decisiones y transición a investigación.',['Memorizar únicamente “6 meses”.','Leer varias veces el artículo sin practicar decisiones.'],['pgn-convocatoria-104-v4','pgn-guia-disciplinaria']),

  m(3,'Estrategia para la prueba de conocimientos','Cobertura, prioridad y meta competitiva.','El 65/100 es umbral de aprobación, no una meta suficiente de preparación. La estrategia debe buscar rendimiento estable y alto, especialmente en los temas directamente conectados con las funciones del empleo.',[
    'Un puntaje global puede ocultar debilidades críticas por módulo.','Simular sirve para medir transferencia, cobertura y resistencia de atención.','La carga de estudio se reasigna con base en errores observados.'
  ],['Haz diagnóstico.','Estudia fundamentos.','Alterna práctica específica e integrada.','Cierra con simulacros y análisis de error.'],
  'Obtienes 84 % en Constitución y 50 % en prueba disciplinaria.','Reasignar tiempo hacia disciplinario manteniendo repasos breves de lo ya fuerte.',['Repartir siempre el mismo tiempo entre todos los temas.','Detener el estudio porque el promedio supera 65.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-concurso-2026']),

  m(4,'Tu profesión dentro del expediente','Aporte técnico, límites y lenguaje profesional.','La experticia profesional sirve para responder preguntas técnicas con método, datos, trazabilidad y limitaciones. No convierte al profesional en autoridad de juzgamiento ni autoriza a afirmar dolo, culpa o responsabilidad fuera de su rol.',[
    'Hecho técnico, inferencia técnica y conclusión jurídica son niveles distintos.','La reproducibilidad fortalece un informe.','Decir “no es posible concluir con estos datos” puede ser técnicamente correcto.'
  ],['Define la pregunta técnica.','Preserva insumos.','Aplica método explicable.','Reporta resultados y límites.'],
  'Un log muestra autenticación de una cuenta a las 08:15 y el jefe exige que el informe afirme quién cometió la falta.','Describir lo demostrable, explicar límites de atribución y dejar la valoración jurídica al competente.',['Afirmar autoría personal solo por el usuario lógico.','Eliminar los datos técnicos para evitar comprometerse.'],['pgn-convocatoria-104-v4','pgn-guia-pruebas','ley-527-1999']),

  m(5,'Constitución y Estado Social de Derecho','Derechos, debido proceso y límites del poder público.','Colombia es un Estado Social de Derecho. Dignidad, derechos, legalidad y debido proceso condicionan la actuación pública; el interés general no habilita a sacrificar garantías para obtener resultados más rápidos.',[
    'El debido proceso también rige actuaciones administrativas.','Los servidores responden por omisión y extralimitación, además de infracción normativa.','La prevalencia del interés general opera dentro de la Constitución.'
  ],['Identifica derecho o principio.','Ubica la función pública ejercida.','Verifica competencia y procedimiento.','Escoge una actuación eficaz y garantista.'],
  'Para acelerar una investigación se propone omitir una comunicación exigida al disciplinable.','Mantener la comunicación y el procedimiento; celeridad no desplaza defensa.',['Omitirla porque hay interés público.','Omitirla si el expediente parece suficientemente probado.'],['constitucion','ley-1952-2019']),

  m(6,'Estructura del Estado colombiano','Ramas, órganos autónomos y organismos de control.','La organización estatal distribuye funciones entre ramas del poder y órganos autónomos. La Procuraduría integra el Ministerio Público y no pertenece ni al Ejecutivo ni a la Rama Judicial.',[
    'Disciplinario, fiscal y penal tienen objetos y autoridades diferentes.','Una misma conducta puede ser relevante en varios regímenes.','La autonomía de responsabilidades impide tratarlas como procesos idénticos.'
  ],['Clasifica la entidad.','Identifica su función constitucional.','Separa tipos de control.','Evita trasladar competencias entre órganos.'],
  'Fiscalía, Contraloría y Procuraduría revisan hechos relacionados con un contrato.','Distinguir objeto y competencia de cada actuación antes de inferir efectos entre ellas.',['Asumir que solo puede existir un proceso.','Tratar cualquier decisión de una de ellas como idéntica a las demás.'],['constitucion','decreto-262-2000']),

  m(7,'Función administrativa y principios','Legalidad, igualdad, moralidad, eficacia, economía, celeridad, imparcialidad y publicidad.','La función administrativa sirve a los intereses generales dentro de principios constitucionales. Eficacia y celeridad no son atajos para desconocer competencia, igualdad, defensa o publicidad.',[
    'Imparcialidad excluye favoritismos personales.','Publicidad admite reservas únicamente con fundamento jurídico.','Coordinación permite que entidades y dependencias actúen de forma coherente.'
  ],['Define el fin público.','Verifica competencia.','Controla garantías y uso de recursos.','Deja trazabilidad de la decisión.'],
  'Un servidor acelera el trámite de un conocido porque “de todos modos cumple requisitos”.','Aplicar criterios objetivos y el orden institucional sin privilegios.',['Favorecerlo porque el resultado sería el mismo.','Compensar favoreciendo luego a otra persona.'],['constitucion','cpaca']),

  m(8,'Servidor público y responsabilidad','Deber funcional y pluralidad de responsabilidades.','El servidor ejerce funciones atribuidas por el ordenamiento. Una conducta puede generar responsabilidad disciplinaria, penal, fiscal u otras, pero cada régimen tiene objeto, autoridad y procedimiento propios.',[
    'La omisión importa cuando existía deber de actuar.','La extralimitación también compromete la función.','Una absolución en un régimen no se traslada mecánicamente a todos los demás.'
  ],['Identifica calidad del sujeto.','Define el deber concreto.','Separa hecho y consecuencia jurídica.','Ubica autoridad competente.'],
  'Un hecho contractual puede tener efectos fiscales y disciplinarios.','Analizar cada dimensión por separado y coordinar información cuando exista deber de hacerlo.',['Declarar responsabilidad fiscal dentro del disciplinario.','Ignorar otras dimensiones incluso cuando deba informarse.'],['constitucion','ley-1952-2019','ley-1474-2011']),

  m(9,'Organización territorial','Nación, departamentos, distritos, municipios y autonomía.','Colombia es una república unitaria descentralizada. La autonomía territorial existe dentro de la Constitución y la ley y no equivale a soberanía ni a competencia ilimitada.',[
    'Materia, sujeto y territorio pueden influir simultáneamente en competencia.','Coordinación, concurrencia y subsidiariedad ayudan a entender relaciones entre niveles.','Lugar físico del hecho no resuelve por sí solo quién debe actuar.'
  ],['Identifica nivel territorial.','Ubica materia.','Revisa competencia específica.','Relaciona territorio con estructura de PGN.'],
  'Hechos involucran una entidad departamental y ocurrieron en dos municipios.','Consultar reglas funcionales y territoriales antes de asignar el asunto.',['Elegir automáticamente el último municipio.','Asignar a la oficina físicamente más cercana.'],['constitucion','ley-1454-2011','decreto-262-2000']),

  m(10,'Ministerio Público y Procuraduría','Naturaleza constitucional y misiones de control.','La Procuraduría integra el Ministerio Público. Ejerce funciones constitucionales de vigilancia, protección de derechos, defensa del orden jurídico y disciplina, entre otras, mediante competencias legalmente definidas.',[
    'No es un ministerio de la Rama Ejecutiva.','El poder disciplinario no es ilimitado.','Prevención e intervención responden a finalidades distintas de sancionar.'
  ],['Ubica la función constitucional.','Identifica función misional.','Aplica competencia orgánica.','Evita trasladar herramientas de una misión a otra.'],
  'Se detecta un riesgo de vulneración antes de materializarse daño.','Valorar actuación preventiva dentro de competencia sin esperar necesariamente una falta consumada.',['Abrir siempre investigación disciplinaria.','Sancionar preventivamente al posible responsable.'],['constitucion','decreto-262-2000','pgn-guia-preventiva']),

  m(11,'Estructura de la PGN','Nivel central, territorial y dependencias de instrucción.','La PGN distribuye funciones entre dependencias centrales y territoriales, incluidas procuradurías delegadas, regionales, distritales y provinciales. La convocatoria ubica el 3PU-15 en varias dependencias de instrucción y planta global.',[
    'Organigrama expresa distribución de funciones, no solo jerarquía.','Una misma denominación de empleo puede operar en especialidades distintas.','La planta global explica por qué se necesita una base transversal amplia.'
  ],['Identifica dependencia.','Ubica nivel.','Revisa función y competencia.','Conecta tarea concreta con el rol del 3PU-15.'],
  'Un asunto parece corresponder a especialidad distinta de la dependencia receptora.','Verificar reparto y competencia antes de actuaciones sustanciales.',['Actuar de fondo y revisar competencia al final.','Remitir sin leer siquiera el asunto.'],['pgn-convocatoria-104-v4','pgn-manual-v9','decreto-262-2000','decreto-1851-2021']),

  m(12,'Funciones misionales','Disciplinaria, preventiva e intervención sin mezclarlas.','La función disciplinaria determina responsabilidad mediante procedimiento; la preventiva anticipa o mitiga riesgos y vigila gestión; la intervención actúa ante otras autoridades en defensa del orden jurídico, patrimonio y derechos conforme a competencia.',[
    'Un mismo contexto puede activar funciones distintas.','Prevenir no es sancionar por anticipado.','Intervenir no es sustituir la decisión del juez o autoridad.'
  ],['Define si hay falta, riesgo o proceso externo.','Selecciona misión.','Ubica herramientas y límites.','Coordina información sin confundir finalidades.'],
  'Un proceso contractual muestra riesgos antes de adjudicar y no hay falta probada.','Usar herramientas preventivas si procede y mantener separado cualquier análisis disciplinario.',['Formular cargos para evitar el riesgo.','No actuar hasta que exista daño cierto.'],['pgn-guia-preventiva','pgn-guia-disciplinaria','decreto-262-2000']),

  m(13,'Competencia disciplinaria','Sujeto, función, territorio, jerarquía y asignación.','La competencia es presupuesto de validez. Debe comprobarse al iniciar y durante el trámite mediante reglas legales y orgánicas; reparto, delegación y comisión no son sinónimos.',[
    'Competencia no nace por disponibilidad del servidor.','Una comisión habilita una actuación concreta, no todo el proceso.','Separar instrucción y juzgamiento protege imparcialidad.'
  ],['Identifica sujeto.','Ubica materia y territorio.','Consulta regla orgánica.','Documenta reparto y actúa dentro del rol.'],
  'Recibes comisión para practicar una declaración dentro de un proceso ajeno.','Practicar la diligencia dentro del objeto de la comisión y devolver resultado al comitente.',['Decidir además si procede formular cargos.','Cambiar el objeto de la diligencia por conveniencia.'],['decreto-262-2000','decreto-1851-2021','ley-1952-2019','pgn-guia-disciplinaria']),

  m(14,'El 3PU-15 dentro de la instrucción','Apoyo profesional, prueba, análisis y límites decisorios.','El empleo apoya instrucción, practica y recauda pruebas, evacua despachos comisorios, procesa información y elabora informes en su campo profesional. También participa en prevención, atención y sistemas de gestión.',[
    'Apoyar no equivale a poder decidir cualquier asunto.','Practicar prueba exige objeto, método, garantía y registro.','El informe técnico debe responder una pregunta del expediente.'
  ],['Lee asignación.','Define aporte profesional.','Ejecuta con método.','Entrega resultado trazable con límites.'],
  'Te piden certificar intencionalidad a partir de datos que solo muestran cambios de sistema.','Informar lo técnicamente verificable y separar la intencionalidad para valoración jurídica con evidencia adicional.',['Certificar dolo por existir cambio no autorizado.','Negarte a analizar porque el caso es jurídico.'],['pgn-convocatoria-104-v4','pgn-manual-v9','pgn-guia-pruebas']),

  m(15,'Acto administrativo','Decisión, motivación, eficacia y ejecutoriedad.','El acto administrativo es una manifestación unilateral de la administración destinada a producir efectos jurídicos. Para analizarlo importan competencia, finalidad, forma, motivación, procedimiento y forma de publicidad o notificación.',[
    'No todo oficio es acto definitivo.','Expedición y eficacia pueden ocurrir en momentos distintos.','Ejecutoria y ejecución no son la misma idea.'
  ],['Identifica efecto jurídico.','Revisa autor competente.','Comprueba motivación y procedimiento.','Determina comunicación y efectos.'],
  'Un correo solo acusa recibo de una petición.','Tratarlo como acto de trámite/información según su contenido, no como decisión de fondo por el solo origen institucional.',['Tratarlo como acto definitivo porque lo envió una entidad.','Declararlo nulo automáticamente porque no resuelve la petición.'],['cpaca']),

  m(16,'CPACA desde cero','Procedimiento administrativo general y relación con regímenes especiales.','El CPACA organiza principios, actuaciones, interesados, pruebas, decisiones, publicidad y recursos. Cuando existe un procedimiento especial, primero se aplica su regla propia y se analiza el papel supletorio del régimen general cuando jurídicamente corresponda.',[
    'La norma especial gobierna lo específico.','No todo defecto formal produce automáticamente nulidad.','Términos y recursos dependen de la decisión y del régimen aplicable.'
  ],['Detecta procedimiento especial.','Aplica regla específica.','Usa marco general cuando corresponda.','Controla participación, términos y decisión.'],
  'Una opción usa un término del CPACA distinto al expresamente previsto por el CGD para una etapa disciplinaria.','Aplicar la regla especial del CGD.',['Aplicar CPACA por ser la ley general administrativa.','Promediar ambos términos.'],['cpaca','ley-1952-2019']),

  m(17,'Derecho de petición','Modalidades, competencia, términos y respuesta de fondo.','El derecho de petición permite formular solicitudes respetuosas y obtener respuesta pronta, completa y de fondo. La autoridad debe clasificar la solicitud, verificar competencia y manejar correctamente información reservada o personal.',[
    'Responder de fondo no significa conceder lo pedido.','No toda petición tiene el mismo término.','La falta de competencia exige actuar conforme a las reglas de traslado y orientación.'
  ],['Clasifica petición.','Verifica competencia.','Gestiona información/reserva.','Responde clara y oportunamente.'],
  'Un ciudadano pide documentos con datos personales de terceros.','Analizar acceso, reserva y posibilidad de entrega parcial o versión pública.',['Negar todo por existir datos personales en una parte.','Entregar íntegramente todo porque la transparencia es absoluta.'],['ley-1755-2015','ley-1712-2014','ley-1581-2012']),

  m(18,'Transparencia, reserva y datos personales','Máxima publicidad con límites legales.','La información pública se presume accesible, pero reservas constitucionales/legales y protección de datos pueden restringir o modular entrega. En un mismo documento pueden coexistir información pública y datos protegidos.',[
    'Reserva no se presume por incomodidad.','Puede existir entrega parcial, anonimización o versión pública.','Accesos a sistemas deben corresponder a finalidad, rol y trazabilidad.'
  ],['Clasifica la información.','Ubica base legal de acceso/restricción.','Minimiza exposición.','Documenta decisión y controles.'],
  'Piden actuaciones de un expediente junto con teléfonos personales de terceros.','Entregar lo procedente y proteger datos no divulgables, evaluando versión parcial.',['Entregar todo.','Negar todo el expediente.'],['ley-1712-2014','ley-1581-2012','cpaca']),

  m(19,'Teoría general del proceso','Sujetos, actos, etapas, términos, cargas, recursos y nulidades.','Un proceso es una secuencia regulada de actos orientados a una decisión. Entender su arquitectura evita escoger figuras jurídicas correctas en la etapa equivocada.',[
    'Etapa determina oportunidad de una actuación.','Recurso solo procede cuando la ley lo permite.','Carga procesal no equivale a deber de la autoridad.'],['Ubica sujetos y competencia.','Construye cronología.','Clasifica actos de impulso, prueba y decisión.','Comprueba contradicción, recursos y saneamiento.'],
  'El expediente está en investigación y una opción propone imponer sanción definitiva.','Descartar el salto de etapa y escoger actuación propia de investigación.',['Aceptar porque la evidencia parece contundente.','Suspender indefinidamente sin decisión.'],['cpaca','ley-1952-2019','pgn-guia-disciplinaria']),

  m(20,'Principios del Derecho Disciplinario','Legalidad, debido proceso, dignidad, presunción de inocencia y culpabilidad.','El Derecho Disciplinario protege el correcto ejercicio de la función pública mediante un procedimiento sometido a legalidad y garantías. No existe responsabilidad objetiva: para sancionar no basta demostrar que ocurrió un resultado; deben acreditarse conducta, ilicitud sustancial, culpabilidad y demás presupuestos aplicables, con respeto pleno al debido proceso.',[
    'La presunción de inocencia permanece hasta una decisión ejecutoriada que establezca responsabilidad.','La duda razonable no se reemplaza por intuiciones sobre lo que “seguramente ocurrió”.','Legalidad y favorabilidad limitan la potestad disciplinaria y orientan la interpretación de las reglas.'
  ],['Identifica el deber funcional y la conducta atribuida.','Separa ocurrencia del hecho de responsabilidad personal.','Verifica ilicitud sustancial, culpabilidad y causales de exclusión.','Comprueba que la actuación respete defensa, contradicción y competencia.'],
  'Un expediente demuestra que hubo un error administrativo, pero todavía no establece quién lo produjo ni si existió dolo o culpa.','Continuar la investigación probatoria sin presumir responsabilidad por el solo resultado.',['Formular cargos únicamente porque el resultado fue irregular.','Asignar responsabilidad al superior por su cargo, sin prueba sobre su conducta.'],['ley-1952-2019','ley-2094-2021','pgn-guia-disciplinaria']),

  m(21,'Sujetos disciplinables y origen de la actuación','Quién puede ser investigado y cómo llega una noticia disciplinaria.','La actuación disciplinaria puede originarse por información, queja, informe u oficio, pero la mera recepción de una afirmación no convierte a una persona en responsable ni obliga a adoptar automáticamente la misma decisión procesal. Primero se verifica relevancia disciplinaria, calidad del sujeto, competencia y grado de identificación del posible autor.',[
    'Una queja es fuente de información, no prueba automática de responsabilidad.','La calidad de sujeto disciplinable debe analizarse para la época de la conducta y conforme al régimen aplicable.','Cuando una noticia no tiene relevancia disciplinaria o carece manifiestamente de fundamento, la respuesta procesal no es inventar una investigación.'
  ],['Lee la noticia sin asumir que es cierta.','Identifica hechos concretos, sujeto y deber posiblemente comprometido.','Verifica competencia y necesidad de indagación o investigación.','Define la actuación procedente y documenta su fundamento.'],
  'Una queja anónima afirma de forma genérica que “todos en la oficina son corruptos”, sin hechos, fechas ni actuaciones identificables.','Evaluar su contenido y suficiencia conforme al régimen antes de abrir una investigación indiscriminada.',['Abrir investigación contra toda la dependencia.','Tomar el anonimato como prueba suficiente de una falta gravísima.'],['ley-1952-2019','pgn-guia-disciplinaria']),

  m(22,'Falta disciplinaria, ilicitud sustancial y culpabilidad','Cómo pasar del hecho irregular a una hipótesis jurídicamente válida.','Una irregularidad solo adquiere sentido disciplinario cuando se conecta con un deber funcional y afecta sustancialmente ese deber sin justificación. Además, la responsabilidad exige culpabilidad: debe establecerse la modalidad subjetiva que corresponda, evitando cualquier forma de responsabilidad objetiva.',[
    'Hecho irregular y falta disciplinaria no son sinónimos.','La ilicitud sustancial se estudia respecto del deber funcional, no por la mera infracción formal aislada.','Dolo y culpa requieren análisis propio; no se deducen automáticamente del resultado.'
  ],['Reconstruye el hecho con precisión.','Identifica deber, prohibición o regla funcional relevante.','Analiza afectación sustancial y posibles justificaciones.','Examina culpabilidad y evidencia que la soporta.'],
  'Un servidor entrega un informe un día tarde por una caída institucional documentada del sistema.','Analizar deber, contexto, afectación y justificación antes de concluir que existe falta disciplinaria.',['Sancionar porque cualquier incumplimiento temporal es falta.','Descartar el caso sin verificar si existían alternativas o deberes de contingencia.'],['ley-1952-2019','pgn-guia-disciplinaria']),

  m(23,'Deberes, prohibiciones, incompatibilidades e impedimentos','El mapa normativo de lo que un servidor debe hacer o evitar.','El análisis disciplinario parte de un deber funcional concreto. Deberes, prohibiciones, incompatibilidades, inhabilidades, impedimentos y conflictos de interés cumplen finalidades distintas y no deben intercambiarse. Ante un conflicto o impedimento, la actuación correcta exige reconocerlo y tramitarlo conforme a la regla aplicable.',[
    'No toda relación personal configura automáticamente una incompatibilidad, pero puede exigir revisar impedimento o conflicto.','La prohibición describe una conducta vedada; el deber impone una conducta esperada.','La competencia no se conserva por conveniencia cuando existe una causal legal que obliga a apartarse.'
  ],['Identifica la relación jurídica relevante.','Clasifica si se trata de deber, prohibición, inhabilidad, incompatibilidad o impedimento.','Ubica la regla y el procedimiento aplicable.','Documenta la actuación de forma transparente.'],
  'Un funcionario debe intervenir en un asunto en el que participa una persona con la que mantiene una relación que puede comprometer su imparcialidad.','Examinar la causal aplicable y tramitar oportunamente el impedimento o conflicto, sin decidir de fondo mientras corresponda apartarse.',['Continuar porque considera que personalmente puede ser objetivo.','Resolver rápido y revelar la relación solo después.'],['ley-1952-2019','ley-1474-2011','constitucion']),

  m(24,'Clasificación, sanciones y prescripción','Gravedad, consecuencias y límites temporales de la acción disciplinaria.','La clasificación de una falta y la eventual sanción dependen de criterios jurídicos que deben demostrarse en el expediente; no se escogen por intuición ni por presión pública. La prescripción limita temporalmente la potestad disciplinaria y exige construir cronologías rigurosas, considerando reglas generales, conductas especiales y eventos de interrupción definidos por la ley.',[
    'La gravedad de la consecuencia no autoriza a rebajar el estándar probatorio.','Prescripción se calcula con fechas jurídicamente relevantes, no con la fecha en que alguien “se enteró” salvo regla expresa.','La notificación de determinadas decisiones puede producir efectos sobre el cómputo conforme al CGD.'
  ],['Identifica naturaleza de la conducta.','Construye línea de tiempo con inicio, continuidad o terminación.','Aplica término y reglas especiales.','Verifica interrupción, efectos y estado actual antes de decidir.'],
  'Un expediente antiguo contiene varias fechas y alguien propone archivarlo solo porque han pasado más de cinco años desde una noticia posterior.','Reconstruir primero la cronología legal de la conducta y aplicar las reglas de prescripción antes de decidir.',['Archivar usando la primera fecha que aparezca en el expediente.','Ignorar prescripción porque la conducta parece grave.'],['ley-1952-2019','ley-2094-2021','pgn-guia-disciplinaria']),

  m(25,'Noticia disciplinaria y evaluación inicial','De la queja o informe a una decisión procesal razonada.','El primer reto de instrucción es convertir información desordenada en hechos disciplinariamente relevantes. El operador debe identificar qué se afirma, quién podría estar involucrado, qué deber funcional podría estar comprometido, qué información falta y qué decisión inicial permite avanzar sin prejuzgar.',[
    'Una noticia puede contener hechos verificables mezclados con opiniones o conclusiones jurídicas del denunciante.','No toda inconformidad ciudadana describe una falta disciplinaria.','La decisión inicial debe ser proporcional al grado real de información disponible.'
  ],['Extrae hechos, fechas, actores y soportes.','Separa hechos de calificativos.','Verifica sujeto, deber y competencia.','Define si corresponde inhibirse, indagar, investigar u otra actuación permitida.'],
  'Una persona afirma que un servidor “abusó de su cargo”, pero solo aporta un correo donde el servidor solicita completar un requisito legal faltante.','Analizar objetivamente el hecho y la regla antes de asumir que la calificación del quejoso describe una falta.',['Abrir investigación porque se usó la expresión “abuso”.','Archivar solo porque el correo tiene apariencia formal.'],['ley-1952-2019','pgn-guia-investigacion','pgn-guia-disciplinaria']),

  m(26,'Indagación previa','Cuándo procede, para qué sirve y cómo termina.','La indagación previa no es una etapa obligatoria de todo expediente. Conforme al Código General Disciplinario, procede cuando existe duda sobre la identificación o individualización del posible autor; tiene un término definido y culmina con archivo definitivo o apertura de investigación, con reglas especiales para violaciones de Derechos Humanos o DIH.',[
    'Su finalidad principal no es investigar indefinidamente “a ver qué aparece”.','La regla general de duración es seis meses.','En asuntos de Derechos Humanos o DIH el término puede extenderse en los términos legales.'
  ],['Confirma que existe duda sobre la identidad del posible autor.','Define diligencias estrictamente útiles para individualizarlo.','Controla término y resultados.','Decide archivo o apertura de investigación según la información obtenida.'],
  'Se conoce perfectamente la identidad del servidor y existen hechos concretos que ameritan investigación, pero se propone abrir indagación previa “por costumbre”.','Evaluar directamente la procedencia de investigación en vez de usar una etapa cuyo presupuesto no está presente.',['Abrir indagación siempre porque debe anteceder a la investigación.','Extender la indagación indefinidamente hasta lograr certeza total.'],['ley-1952-2019','ley-2094-2021','pgn-guia-investigacion']),

  m(27,'Investigación disciplinaria','Finalidad, apertura, término y plan de trabajo.','La investigación disciplinaria inicia cuando se identifica al posible autor y busca verificar la ocurrencia de la conducta, su eventual relevancia disciplinaria y la posible presencia de causales de exclusión. La apertura debe precisar hechos relevantes y pruebas iniciales, y la investigación se dirige con imparcialidad, términos controlados y un plan probatorio coherente.',[
    'La decisión de apertura no es una formulación de cargos anticipada.','La investigación debe buscar evidencia tanto incriminatoria como exculpatoria.','Los términos tienen reglas de extensión para supuestos específicos; no son autorizaciones para inactividad.'
  ],['Formula hechos disciplinariamente relevantes en lenguaje claro.','Define hipótesis y preguntas probatorias.','Ordena e incorpora evidencia pertinente.','Revisa periódicamente suficiencia, términos y causales de terminación.'],
  'El expediente contiene evidencia que contradice la hipótesis inicial y el investigador propone omitirla porque “debilita el caso”.','Incorporar y valorar evidencia favorable y desfavorable con igual rigor.',['Excluirla para conservar una teoría del caso consistente.','Archivar inmediatamente sin analizar el conjunto probatorio.'],['ley-1952-2019','ley-2094-2021','pgn-guia-investigacion','pgn-guia-pruebas']),

  m(28,'Sujetos procesales, defensa y versión libre','Participación, contradicción y prohibición de prejuzgar.','El disciplinable y los demás intervinientes reconocidos por la ley participan con garantías específicas. La versión libre es un instrumento de defensa y no puede tratarse como una obligación de autoincriminación. La instrucción debe permitir contradicción y acceso en los términos aplicables sin convertir la relación procesal en una lucha personal.',[
    'Guardar silencio no equivale a confesar.','La versión debe valorarse junto con el resto del material probatorio.','Comunicar oportunamente decisiones y pruebas hace posible una defensa real, no meramente formal.'
  ],['Identifica quién tiene calidad procesal.','Informa derechos y actuaciones que correspondan.','Permite ejercer defensa y contradicción.','Valora cada intervención dentro del conjunto probatorio.'],
  'Durante versión libre el disciplinable decide no responder una pregunta y el funcionario propone registrar ese silencio como indicio de culpabilidad.','Respetar la garantía de no autoincriminación y no convertir el silencio en prueba automática de responsabilidad.',['Considerar el silencio confesión implícita.','Suspender indefinidamente el proceso hasta que responda.'],['ley-1952-2019','constitucion','pgn-guia-disciplinaria']),

  m(29,'Cierre de investigación y alegatos precalificatorios','Cuándo termina la fase investigativa y qué ocurre antes de evaluar.','Cuando se han recaudado las pruebas ordenadas o vencido el término correspondiente, la investigación debe cerrarse conforme al CGD. La etapa posterior permite a los sujetos procesales presentar alegatos precalificatorios dentro del término legal antes de que el instructor evalúe si procede archivo o formulación de cargos.',[
    'Cerrar la investigación no significa que ya exista responsabilidad.','Los alegatos precalificatorios son oportunidad de defensa antes de la evaluación.','La evaluación debe considerar integralmente hechos, pruebas, argumentos y reglas aplicables.'
  ],['Verifica prueba pendiente y término.','Adopta y comunica el cierre cuando proceda.','Respeta oportunidad de alegatos precalificatorios.','Evalúa el expediente sin omitir argumentos relevantes.'],
  'El instructor considera que la evidencia es suficiente y quiere formular cargos el mismo día del cierre sin habilitar la oportunidad legal de alegatos.','Respetar la secuencia procesal y la oportunidad de alegatos antes de evaluar y decidir.',['Formular cargos de inmediato por economía procesal.','Mantener abierta la investigación indefinidamente para evitar el trámite.'],['ley-1952-2019','ley-2094-2021','pgn-guia-investigacion']),

  m(30,'Archivo o formulación de cargos','Dos decisiones motivadas, no premio y castigo.','Al finalizar la instrucción, el expediente debe evaluarse para determinar si existen presupuestos suficientes para formular cargos o si procede terminación y archivo. Los cargos delimitan jurídicamente la acusación disciplinaria y deben apoyarse en material probatorio; el archivo también exige motivación y no puede usarse para ocultar vacíos investigativos subsanables dentro del término.',[
    'Formular cargos no equivale a sancionar.','La decisión debe corresponder con hechos y evidencia recaudada, no con rumores externos.','El archivo procede por causales y conclusiones jurídicamente sustentadas.'
  ],['Resume hechos acreditados y no acreditados.','Relaciona deber funcional y posible falta.','Analiza evidencia y culpabilidad con el estándar de la etapa.','Motiva cargos o archivo y garantiza comunicación correspondiente.'],
  'Solo existe una sospecha consistente, pero ninguna evidencia permite vincular personalmente al investigado con la conducta atribuida.','Evaluar si el estándar para cargos está realmente satisfecho y no suplir evidencia con sospechas.',['Formular cargos para que juzgamiento “aclare” lo faltante.','Declarar responsabilidad definitiva desde la instrucción.'],['ley-1952-2019','pgn-guia-investigacion','pgn-guia-disciplinaria']),

  m(31,'Notificaciones, comunicaciones y recursos disciplinarios','La forma de enterar y controvertir también es debido proceso.','Cada decisión disciplinaria debe analizarse según su naturaleza para determinar cómo se comunica o notifica, desde cuándo produce determinados efectos y qué recursos proceden. No existe una fórmula universal: la respuesta depende de la decisión concreta y de las reglas especiales del CGD.',[
    'Publicar, comunicar y notificar no son sinónimos.','Un recurso improcedente no se vuelve procedente por invocar el derecho de defensa.','La oportunidad para recurrir exige identificar correctamente la forma y fecha de conocimiento jurídico de la decisión.'
  ],['Clasifica la decisión.','Determina forma de comunicación/notificación.','Identifica recurso, legitimación y término.','Registra constancias y controla ejecutoria.'],
  'Se interpone un recurso contra una decisión para la cual la ley no lo contempla.','Verificar expresamente procedencia y tramitar conforme al régimen, explicando la regla aplicable.',['Conceder cualquier recurso por precaución.','Ignorar el escrito sin dejar decisión o explicación.'],['ley-1952-2019','ley-2094-2021','pgn-guia-disciplinaria']),

  m(32,'Irregularidades y nulidades','Corregir defectos sin convertir cualquier error en nulidad total.','La nulidad protege garantías fundamentales del proceso y responde a causales y efectos jurídicos definidos. No todo error formal destruye lo actuado: debe analizarse su relevancia, afectación real y posibilidad de corrección o saneamiento, preservando las actuaciones válidas cuando jurídicamente corresponda.',[
    'Nulidad no es una sanción al funcionario por cometer cualquier equivocación.','Debe existir vínculo entre defecto y garantía o causal jurídica relevante.','Corregir tempranamente un defecto puede evitar que contamine decisiones posteriores.'
  ],['Identifica el defecto concreto.','Determina garantía, causal y trascendencia.','Evalúa corrección, saneamiento y alcance.','Decide motivadamente preservando lo válido cuando sea posible.'],
  'Una fecha fue digitada erróneamente en una constancia, pero existe soporte inequívoco de la fecha real y no se afectó defensa.','Analizar corrección del error y su trascendencia antes de declarar nulidad de todo el proceso.',['Anular siempre el expediente completo por cualquier error.','Ignorar el defecto aun cuando pueda generar confusión futura.'],['ley-1952-2019','ley-2094-2021','pgn-guia-disciplinaria']),

  m(33,'Despachos comisorios','Practicar una diligencia fuera del alcance inmediato sin asumir el proceso ajeno.','La comisión permite encargar a otra autoridad o dependencia la práctica de una actuación concreta dentro de los límites definidos. El comisionado debe comprender objeto, sujetos, diligencia, formalidades y soportes; después devuelve resultado al comitente, sin apropiarse de decisiones que no le fueron delegadas.',[
    'Comisión es una habilitación delimitada, no transferencia general del expediente.','El objeto de la diligencia debe quedar suficientemente claro.','El resultado debe regresar con trazabilidad, constancias y anexos necesarios.'
  ],['Lee integralmente el despacho.','Verifica competencia y objeto concreto.','Practica la diligencia respetando garantías.','Documenta resultado y devuelve al comitente.'],
  'Te comisionan para recibir un testimonio y durante la diligencia surge una solicitud de archivo del proceso.','Practicar la diligencia comisionada y remitir la petición al funcionario competente para decidirla.',['Resolver el archivo porque ya tienes el expediente temporalmente.','Negarte a recibir el testimonio porque no diriges el proceso principal.'],['ley-1952-2019','pgn-guia-disciplinaria','pgn-guia-pruebas']),

  m(34,'Separación entre instrucción y juzgamiento','Imparcialidad estructural y límites del rol del instructor.','La reforma disciplinaria reforzó la separación funcional entre investigación/acusación y juzgamiento para asegurar imparcialidad. Quien apoya la instrucción debe construir y entregar un expediente íntegro, comprensible y contradictorio, sin asumir funciones de decisión sancionatoria que correspondan a la etapa de juzgamiento.',[
    'La teoría del caso del instructor no sustituye la valoración independiente del juzgador.','Un buen expediente incluye también evidencia favorable al disciplinable.','Transferir el expediente exige orden, integridad y claridad sobre actuaciones pendientes.'
  ],['Cierra técnicamente la instrucción.','Organiza expediente y metadatos.','Identifica decisiones adoptadas y recursos.','Entrega sin anticipar la decisión final de responsabilidad.'],
  'El instructor considera “obvia” la culpabilidad y propone redactar desde ya la sanción que debería imponer el juzgador.','Limitarse a la función instructiva y sustentar la acusación cuando proceda, preservando independencia de juzgamiento.',['Definir la sanción para ahorrar tiempo.','Ocultar evidencia exculpatoria para fortalecer los cargos.'],['ley-2094-2021','ley-1952-2019','pgn-guia-disciplinaria']),

  m(35,'Necesidad, carga de la prueba e imparcialidad','La decisión disciplinaria debe apoyarse en prueba legal y suficiente.','La carga de demostrar los elementos relevantes corresponde al Estado dentro del proceso disciplinario. La autoridad debe buscar con igual rigor evidencia que comprometa y que favorezca al investigado; el objetivo no es “ganar un caso”, sino aproximarse de manera objetiva a los hechos dentro de las garantías procesales.',[
    'La ausencia de explicación del investigado no llena vacíos probatorios de la administración.','Una hipótesis debe poder ser falsada por la evidencia, no blindarse frente a ella.','Prueba incriminatoria y exculpatoria se valoran dentro del mismo estándar de racionalidad.'
  ],['Define qué hechos necesitan prueba.','Asigna una pregunta probatoria a cada elemento.','Busca fuentes independientes a favor y en contra.','Valora suficiencia antes de afirmar conclusión.'],
  'La única evidencia es que el investigado tenía permiso técnico para modificar un sistema, pero no hay registro de que lo haya hecho.','No convertir capacidad de acceso en prueba de ejecución; recaudar evidencia adicional sobre el evento concreto.',['Concluir autoría porque podía hacerlo.','Exigir al investigado que demuestre que no fue él.'],['ley-1952-2019','pgn-guia-pruebas']),

  m(36,'Pertinencia, conducencia y utilidad','Elegir prueba por lo que puede demostrar, no por acumulación.','Una prueba útil debe relacionarse con un hecho relevante y aportar razonablemente a su esclarecimiento dentro de las reglas del medio empleado. Pedir grandes volúmenes de información sin pregunta probatoria clara puede afectar eficiencia, privacidad y calidad del análisis sin mejorar la verdad del proceso.',[
    'Pertinencia conecta la prueba con el hecho debatido.','Conducencia examina si el medio es jurídicamente idóneo cuando existen reglas específicas.','Utilidad evita diligencias redundantes o incapaces de aportar información relevante.'
  ],['Formula el hecho a probar.','Explica qué información esperas obtener.','Selecciona medio idóneo y alcance proporcional.','Descarta duplicidad y documenta decisión.'],
  'Para investigar una modificación ocurrida en una hora concreta se propone copiar diez años de correos personales de todos los servidores.','Delimitar temporal, material y subjetivamente la solicitud a información pertinente, útil y jurídicamente obtenible.',['Recolectar todo porque más datos siempre significan mejor prueba.','No solicitar ninguna evidencia digital para evitar problemas de privacidad.'],['ley-1952-2019','pgn-guia-pruebas','ley-1581-2012']),

  m(37,'Legalidad, exclusión y contradicción de la prueba','La verdad procesal no puede construirse a cualquier precio.','La prueba debe obtenerse y practicarse respetando Constitución, ley y garantías. La evidencia obtenida con violación de derechos puede enfrentar consecuencias de exclusión o invalidez según el régimen aplicable; además, los sujetos procesales deben poder conocer y controvertir la evidencia en las condiciones legales.',[
    'Que una evidencia sea técnicamente auténtica no resuelve por sí sola si fue obtenida legalmente.','La contradicción permite cuestionar origen, método, significado y conclusiones.','Prueba proveniente de otro proceso exige revisar condiciones de incorporación y posibilidad de contradicción.'
  ],['Revisa origen y autorización.','Comprueba integridad y cadena documental.','Determina reglas de incorporación.','Garantiza contradicción antes de soportar una decisión.'],
  'Un tercero entrega una grabación cuya obtención podría haber vulnerado derechos y se propone usarla de inmediato por ser “muy clara”.','Examinar primero legalidad de obtención, incorporación y contradicción antes de atribuirle valor.',['Usarla porque demuestra aparentemente el hecho.','Eliminarla físicamente sin registrar que fue aportada.'],['ley-1952-2019','constitucion','pgn-guia-pruebas']),

  m(38,'Plan probatorio e hipótesis de investigación','Investigar con preguntas, no con acumulación de documentos.','Un plan probatorio traduce los hechos jurídicamente relevantes en preguntas verificables, identifica fuentes y ordena diligencias según dependencia, costo, riesgo de pérdida y capacidad explicativa. La matriz permite distinguir qué está acreditado, qué es inferencia y qué sigue abierto.',[
    'Una hipótesis útil admite evidencia que pueda confirmarla o refutarla.','Cronología y matriz de hechos evitan perder relaciones entre fuentes.','La investigación debe actualizar su plan cuando nueva evidencia cambia el problema.'
  ],['Lista hechos jurídicamente relevantes.','Convierte cada hecho en pregunta probatoria.','Asocia fuentes independientes y orden de recaudo.','Registra resultado, contradicciones y vacíos.'],
  'Tres sistemas registran horas distintas para el mismo evento por zonas horarias no normalizadas.','Añadir al plan la verificación de relojes, zonas horarias y fuente temporal antes de construir la cronología definitiva.',['Elegir el sistema que apoye mejor la hipótesis inicial.','Promediar las horas para obtener una hora “probable”.'],['pgn-guia-investigacion','pgn-guia-pruebas','ley-1952-2019']),

  m(39,'Sana crítica, indicios y valoración conjunta','De la evidencia a una conclusión explicable.','La sana crítica exige valorar racionalmente la evidencia con reglas de lógica, experiencia y conocimiento técnico, explicando por qué una fuente merece determinado peso y cómo se relaciona con las demás. Un indicio requiere un hecho indicador acreditado y una inferencia razonada hacia el hecho indicado.',[
    'Cantidad de documentos no equivale a fuerza probatoria si todos repiten la misma fuente.','Corroboración independiente vale más que duplicación de un mismo dato.','Una inferencia debe identificar alternativas plausibles y explicar por qué se aceptan o descartan.'
  ],['Acredita primero el hecho indicador.','Formula la inferencia con premisas explícitas.','Contrasta hipótesis alternativas.','Valora el conjunto y expresa límites de certeza.'],
  'Cinco informes internos repiten exactamente una acusación originada en un solo correo sin verificación adicional.','Reconocer que existen cinco documentos, pero una sola fuente material no corroborada, y buscar evidencia independiente.',['Contarlos como cinco pruebas independientes.','Descartarlos todos sin revisar el correo original.'],['ley-1952-2019','pgn-guia-pruebas']),

  m(40,'Prueba documental física y electrónica','Origen, autenticidad, integridad, contexto y fuerza demostrativa.','Un documento puede contener información relevante sin que ello resuelva automáticamente quién lo creó, si fue modificado, en qué contexto surgió o qué demuestra exactamente. En documentos electrónicos deben diferenciarse contenido, metadatos, firma, sistema de origen, copia, exportación y mecanismos de integridad.',[
    'Autenticidad busca establecer correspondencia con su autor u origen; integridad se refiere a conservación del contenido.','Una captura de pantalla puede ser útil, pero normalmente ofrece menos contexto verificable que la fuente original o su extracción controlada.','El valor del documento depende también de su relación con otros elementos probatorios.'
  ],['Identifica fuente y formato original.','Preserva o documenta la adquisición.','Verifica metadatos, integridad y contexto cuando sea relevante.','Explica qué demuestra y qué no demuestra.'],
  'Se aporta una captura de una conversación sin fecha completa ni identificación técnica del dispositivo o cuenta.','Tratarla como elemento que requiere contextualización y corroboración, buscando la fuente y soportes adicionales.',['Dar por probados autoría, fecha y contenido únicamente por la imagen.','Descartarla automáticamente por ser una captura.'],['ley-1952-2019','pgn-guia-pruebas','ley-527-1999']),

  m(41,'Testimonio, confesión y memoria','Cómo valorar relatos sin confundir seguridad con exactitud.','El testimonio aporta percepciones y recuerdos de una persona; debe analizarse su oportunidad de percepción, coherencia, precisión, posibles sesgos y corroboración. La confesión tiene reglas y efectos propios y nunca debe confundirse con una afirmación obtenida sin garantías o con el simple silencio del disciplinable.',[
    'Una persona segura de su recuerdo puede estar equivocada.','Diferencias periféricas no destruyen necesariamente un relato, pero contradicciones centrales exigen explicación.','Preguntas sugestivas o contaminantes pueden afectar la calidad de la información obtenida.'
  ],['Define el hecho sobre el que declarará la persona.','Explora condiciones de percepción y memoria.','Distingue conocimiento directo de lo oído a terceros.','Contrasta el relato con evidencia independiente.'],
  'Un testigo afirma con mucha seguridad haber visto una acción, pero estaba a gran distancia y su relato contradice registros objetivos de horario.','Valorar condiciones de percepción y contradicciones sin equiparar seguridad subjetiva con verdad.',['Dar prioridad absoluta al testigo porque habla con convicción.','Descartar todo el testimonio por una inconsistencia menor sin análisis.'],['ley-1952-2019','pgn-guia-pruebas']),

  m(42,'Prueba pericial y conocimiento experto','Método, datos, inferencia técnica y límites.','La peritación ayuda a comprender cuestiones que requieren conocimiento especializado. Su fuerza no depende del título del experto por sí solo, sino de la idoneidad, los datos examinados, el método empleado, la posibilidad de explicar o reproducir el análisis y la claridad sobre supuestos, márgenes de error y limitaciones.',[
    'El perito informa desde su especialidad; no sustituye al funcionario que adopta la decisión jurídica.','Una conclusión sin método verificable es débil aunque provenga de una persona reconocida.','El contradictorio puede cuestionar datos, método, inferencias y alcance de la conclusión.'
  ],['Delimita la pregunta pericial.','Verifica idoneidad y materiales examinados.','Exige método y razonamiento explicables.','Distingue hallazgo técnico de valoración jurídica.'],
  'Un experto concluye “el investigado actuó dolosamente” basándose en un análisis de registros informáticos.','Separar los hallazgos técnicos sobre eventos del sistema de la calificación jurídica de dolo, que corresponde valorar con el conjunto probatorio.',['Aceptar el dolo porque lo afirmó el experto.','Descartar el informe completo por incluir una conclusión excedida.'],['ley-1952-2019','pgn-guia-pruebas']),

  m(43,'Inspección disciplinaria y prueba trasladada','Observar directamente y reutilizar evidencia con garantías.','La inspección permite verificar directamente lugares, cosas, documentos o situaciones relevantes mediante una diligencia formalmente documentada. La prueba proveniente de otra actuación puede ser útil, pero su traslado no elimina la necesidad de revisar origen, legalidad, integridad y oportunidades de contradicción conforme al régimen aplicable.',[
    'La inspección debe tener objeto definido y registro suficiente de lo observado.','Trasladar un documento no significa trasladar automáticamente todas las conclusiones del otro proceso.','Contexto y posibilidad de contradicción condicionan la valoración.'
  ],['Define objeto y alcance.','Documenta participantes, circunstancias y hallazgos.','Si proviene de otro proceso, identifica origen y forma de incorporación.','Permite contradicción y valora autónomamente.'],
  'Una sentencia de otro proceso contiene un resumen de pruebas y se propone copiar su conclusión disciplinaria sin examinar los soportes.','Incorporar lo jurídicamente procedente y valorar de forma autónoma los elementos relevantes dentro del proceso disciplinario.',['Adoptar automáticamente todas las conclusiones externas.','Ignorar cualquier evidencia proveniente de otra actuación.'],['ley-1952-2019','pgn-guia-pruebas']),

  m(44,'Cadena de custodia y preservación digital','Mantener identidad, integridad y trazabilidad desde la adquisición hasta el análisis.','La preservación digital exige documentar qué se recibió, de dónde provino, quién lo manipuló, qué operaciones se realizaron y cómo se verificó que el contenido analizado corresponde al adquirido. Herramientas como hashes ayudan a verificar identidad de bytes, pero no prueban por sí solas autoría, intención ni legitimidad de adquisición.',[
    'Una copia forense o exportación controlada debe conservar la fuente original cuando sea posible y documentar el procedimiento.','La hora de un registro necesita contexto de zona horaria, sincronización y fuente temporal.','Hash igual demuestra coincidencia de contenido binario entre dos objetos comparados, no quién produjo ese contenido.'
  ],['Identifica y aísla la fuente.','Documenta adquisición, responsable, fecha y método.','Calcula/verifica integridad cuando corresponda.','Trabaja sobre copia y registra cada transformación analítica.'],
  'Se exporta una base de logs a Excel, se ordenan filas y después se guarda sobre el mismo archivo sin conservar el export original.','Preservar el original, documentar hash y trabajar en una copia analítica con transformaciones registradas.',['Usar solo el Excel modificado porque contiene la misma información visible.','Imprimir los logs y destruir el archivo digital para simplificar custodia.'],['pgn-guia-pruebas','ley-527-1999','ley-1952-2019']),

  m(45,'Función preventiva integral','Prevenir antes que sancionar sin coadministrar.','La función preventiva busca anticiparse a hechos que puedan afectar derechos o la gestión pública mediante detección temprana de riesgos, advertencia, vigilancia y seguimiento dentro de la competencia de la PGN. No autoriza a sustituir a la entidad vigilada ni a tomar sus decisiones administrativas.',[
    'Prevenir no requiere esperar a que una falta disciplinaria esté consumada.','Advertir un riesgo no equivale a declarar responsable a una persona.','La intervención preventiva debe respetar autonomía de la administración y evitar coadministración.'
  ],['Identifica derecho, política o gestión en riesgo.','Describe causa, probabilidad e impacto con evidencia.','Selecciona herramienta preventiva proporcional.','Hace seguimiento sin asumir la decisión de la entidad vigilada.'],
  'Una entidad aún puede corregir un proceso que presenta un riesgo documentado de vulneración de derechos.','Actuar preventivamente mediante las herramientas competentes, dejando a la entidad la decisión administrativa que le corresponde.',['Ordenar directamente cómo debe adjudicar o gestionar el proceso.','Esperar a que ocurra el daño para recién intervenir.'],['pgn-guia-preventiva','decreto-262-2000','pgn-buenas-practicas-ddhh']),

  m(46,'Sistema Integral de Prevención y tipos de actuación','Planear, ejecutar y evaluar prevención con método.','El Sistema Integral de Prevención articula dependencias, información, normas, lineamientos, principios, mecanismos y herramientas. La gestión preventiva debe partir de análisis, priorización y objetivos verificables; sus actuaciones no son cartas aisladas sino intervenciones que pueden organizarse para anticipar, mitigar u orientar riesgos y hacer seguimiento.',[
    'El riesgo preventivo debe describirse de forma verificable, no como una sospecha genérica.','La priorización usa criterios de impacto, urgencia, población afectada y capacidad institucional.','El cierre de una actuación exige revisar resultados y no solo contar actividades realizadas.'
  ],['Define situación y derechos/gestión afectados.','Analiza riesgo y actores.','Planea actuación con producto e indicador.','Ejecuta, documenta y evalúa resultado.'],
  'Una dependencia envió veinte requerimientos, pero no sabe si el riesgo que motivó la actuación disminuyó.','Revisar resultados e indicadores de efecto, no confundir número de oficios con eficacia preventiva.',['Declarar éxito porque hubo muchas actividades.','Cerrar por agotamiento del cronograma sin analizar el riesgo.'],['pgn-guia-preventiva','pgn-sgc']),

  m(47,'Políticas públicas, control de gestión y análisis de riesgos','Vigilar resultados sin confundir síntoma, causa e indicador.','El control preventivo sobre políticas y gestión requiere comprender objetivos públicos, responsables, recursos, productos, resultados e indicadores. Una desviación puede ser síntoma de múltiples causas; antes de recomendar acciones conviene validar datos, contexto territorial y capacidad de la entidad.',[
    'Un indicador sin denominador o línea base puede inducir conclusiones erróneas.','Producto realizado y resultado social alcanzado no son lo mismo.','Una correlación temporal no demuestra por sí sola causalidad.'
  ],['Reconstruye objetivo y cadena de valor.','Valida fuente y definición del indicador.','Identifica riesgo, causa y controles existentes.','Formula seguimiento o recomendación dentro de competencia.'],
  'Un municipio reporta 90 talleres de prevención, pero aumentó el indicador de vulneración que pretendían reducir.','Analizar cobertura, población objetivo, calidad, contexto y relación entre productos y resultados antes de concluir éxito o fracaso.',['Concluir éxito por el número de talleres.','Concluir causalidad automática entre talleres y aumento del problema.'],['pgn-guia-preventiva','pgn-sgc','decreto-1499-2017']),

  m(48,'Función de intervención','Defender orden jurídico y derechos sin reemplazar al juez o autoridad.','En su función de intervención el Ministerio Público participa ante autoridades judiciales o administrativas en los casos previstos, defendiendo el orden jurídico, el patrimonio público y derechos fundamentales. Intervenir significa aportar una posición institucional dentro del proceso, no asumir la competencia decisoria de la autoridad ante la cual se actúa.',[
    'La intervención debe estar jurídicamente habilitada y motivada.','Un concepto del Ministerio Público puede ser relevante sin ser la sentencia o decisión final.','Disciplinario, preventivo e intervención pueden compartir hechos, pero conservan objetos distintos.'
  ],['Identifica proceso y autoridad que decide.','Verifica habilitación para intervenir.','Construye posición con hechos y normas.','Respeta independencia de la decisión final.'],
  'Durante una intervención, el profesional considera que una medida sería conveniente y propone ejecutarla directamente desde la PGN.','Presentar la posición o solicitud correspondiente y dejar la decisión a la autoridad competente.',['Adoptar directamente la medida.','No intervenir nunca porque solo el juez puede hablar en el proceso.'],['decreto-262-2000','constitucion']),

  m(49,'Población vulnerable y enfoque diferencial','Atender derechos con accesibilidad, dignidad y comprensión del contexto.','El enfoque diferencial reconoce que barreras y riesgos no afectan de la misma forma a todas las personas. La atención debe identificar necesidades de accesibilidad, seguridad, comunicación, género, edad, discapacidad, pertenencia étnica u otras circunstancias relevantes sin estereotipar, exponer datos innecesarios ni revictimizar.',[
    'Trato igual no siempre significa atención idéntica cuando existen barreras objetivas.','La información sensible debe manejarse con necesidad, finalidad y confidencialidad.','El enfoque diferencial complementa la garantía de derechos; no elimina reglas de competencia ni procedimiento.'
  ],['Escucha y detecta barreras concretas.','Pregunta necesidades de ajuste sin asumirlas.','Adapta canal, lenguaje y ruta dentro de competencia.','Protege datos y evita repetición innecesaria del relato.'],
  'Una persona con discapacidad auditiva llega a presentar una queja y la dependencia solo ofrece atención oral sin alternativa accesible.','Gestionar un ajuste razonable o canal accesible que permita una interacción efectiva y digna.',['Pedirle que vuelva con un familiar que hable por ella.','Recibir la queja sin asegurar comprensión porque el procedimiento es igual para todos.'],['ley-1618-2013','constitucion','pgn-buenas-practicas-ddhh','ley-1581-2012']),

  m(50,'Contratación estatal desde cero','Actores, principios y ciclo de un contrato público.','La contratación pública es un instrumento para cumplir fines estatales, no una compra privada con dinero público. Su ciclo conecta planeación de la necesidad, selección del contratista, celebración, ejecución, seguimiento y cierre; los principios de transparencia, economía, responsabilidad, planeación y selección objetiva orientan el análisis.',[
    'La modalidad de selección no se escoge para favorecer a una persona sino conforme a presupuestos legales.','Una necesidad mal planeada contamina riesgos posteriores del contrato.','El expediente contractual debe permitir reconstruir por qué se tomaron decisiones relevantes.'
  ],['Define necesidad y competencia.','Planea objeto, recursos y riesgos.','Aplica modalidad y criterios objetivos.','Supervisa ejecución y documenta cierre.'],
  'Una entidad comienza a recibir un servicio antes de definir claramente alcance, presupuesto y soportes de planeación.','Identificar el riesgo derivado de una contratación sin planeación suficiente y revisar la legalidad de las actuaciones.',['Normalizar todo después con documentos retroactivos.','Asumir que la urgencia elimina cualquier deber de planeación.'],['ley-80-1993','ley-1150-2007','decreto-1082-2015']),

  m(51,'Planeación y selección objetiva','Estudios previos, requisitos, modalidad y evaluación.','La planeación contractual debe justificar necesidad, objeto, valor, riesgos, requisitos y estrategia de selección. La selección objetiva exige criterios vinculados al objeto y verificables; requisitos desproporcionados pueden restringir competencia y señales de especificaciones direccionadas deben analizarse con evidencia, no con intuición.',[
    'Más requisitos no significan automáticamente mejor selección.','Experiencia y capacidad exigidas deben guardar relación con el objeto y los riesgos.','Cambios de reglas durante el proceso requieren justificación, publicidad y respeto de igualdad.'
  ],['Comprende necesidad y mercado.','Relaciona requisitos con riesgo y objeto.','Verifica modalidad y reglas publicadas.','Evalúa ofertas con los mismos criterios definidos.'],
  'Un pliego exige una certificación extraordinariamente específica que solo posee un proveedor y no se explica su necesidad técnica.','Solicitar y analizar la justificación objetiva del requisito y su proporcionalidad frente al objeto.',['Concluir corrupción automáticamente.','Mantener el requisito porque la entidad puede pedir cualquier documento.'],['ley-80-1993','ley-1150-2007','decreto-1082-2015','ley-1474-2011']),

  m(52,'Ejecución, supervisión e interventoría','Seguimiento basado en evidencia y separación de roles.','Durante la ejecución deben verificarse obligaciones, productos, calidad, plazos, pagos, modificaciones y riesgos. Supervisión e interventoría son mecanismos de seguimiento con alcances definidos; certificar cumplimiento requiere evidencia suficiente y no debe convertirse en un trámite automático para liberar pagos.',[
    'Acta firmada no sustituye la verificación material cuando el objeto exige comprobar calidad o cantidad.','Una modificación contractual necesita competencia, fundamento y trazabilidad.','Hallazgos deben gestionarse oportunamente y no acumularse hasta la liquidación.'
  ],['Lee contrato, obligaciones y controles.','Reúne evidencia de ejecución.','Documenta desviaciones y gestiona corrección.','Certifica solo lo realmente verificado y soportado.'],
  'Un supervisor recibe una factura y firma recibido a satisfacción sin comprobar que el servicio mensual se prestó.','Verificar evidencia de cumplimiento antes de certificar y autorizar el trámite correspondiente.',['Firmar porque el contratista siempre ha cumplido.','Negar cualquier pago sin revisar soportes.'],['ley-80-1993','ley-1474-2011','decreto-1082-2015']),

  m(53,'Inhabilidades, incompatibilidades y conflictos en contratación','Prevenir decisiones comprometidas por relaciones o prohibiciones legales.','Las inhabilidades e incompatibilidades contractuales tienen fuente legal y consecuencias específicas. Los conflictos de interés requieren identificar relación, interés y capacidad de afectar imparcialidad. El análisis debe basarse en hechos y normas vigentes para la fecha relevante, evitando presumir impedimentos por simple cercanía social o desconocerlos por conveniencia.',[
    'Una restricción legal no puede crearse por analogía sancionatoria.','El momento temporal de la relación puede ser determinante.','Declarar y tramitar oportunamente un conflicto protege tanto la decisión como al servidor.'
  ],['Identifica personas y vínculos relevantes.','Ubica norma y periodo aplicable.','Determina si hay prohibición, incompatibilidad o conflicto.','Actúa antes de intervenir en la decisión comprometida.'],
  'Un evaluador descubre que uno de los proponentes es una empresa administrada por una persona con quien tiene un vínculo que podría afectar imparcialidad.','Revisar la causal jurídica y tramitar el eventual impedimento o conflicto antes de continuar evaluando.',['Seguir evaluando y contar la relación al final.','Excluir al proponente sin procedimiento ni fundamento.'],['ley-80-1993','ley-1474-2011','constitucion']),

  m(54,'Anticorrupción, transparencia y análisis de señales','Del riesgo o patrón sospechoso a una investigación responsable.','La prevención de corrupción exige controles de transparencia, conflictos, contratación, denuncias y riesgos, pero una señal de alerta no equivale a prueba de delito o falta. El profesional debe distinguir indicador, anomalía, hallazgo y conclusión, preservar información y remitir o investigar conforme a competencia.',[
    'Fraccionamiento aparente, concentración de proveedores o cambios repetidos pueden ser señales que necesitan contexto.','Un algoritmo de riesgo prioriza revisión; no declara responsabilidad.','La protección de denunciantes e información sensible puede ser relevante al gestionar reportes.'
  ],['Identifica patrón y fuente.','Verifica calidad y contexto de datos.','Contrasta explicaciones alternativas.','Escala o documenta conforme a competencia sin etiquetar culpables prematuramente.'],
  'Un tablero marca como “alto riesgo” a un contrato porque tiene varias adiciones, y alguien propone reportar al responsable como corrupto.','Tratar el indicador como señal para revisión documental y jurídica, no como conclusión de responsabilidad.',['Publicar el nombre del servidor como responsable.','Ignorar el indicador porque no es prueba definitiva.'],['ley-1474-2011','ley-2195-2022','ley-1712-2014']),

  m(55,'Ordenamiento territorial','Autonomía, competencias y herramientas de ordenamiento.','El ordenamiento territorial articula competencias entre Nación y entidades territoriales y organiza el uso y ocupación del territorio. POT, PBOT y EOT son instrumentos municipales/distritales con alcances asociados al marco legal; comprenderlos exige distinguir autonomía territorial, competencias sectoriales y límites superiores.',[
    'Autonomía territorial se ejerce dentro de Constitución y ley.','POT no es sinónimo de cualquier plan de desarrollo.','Una decisión sobre suelo puede involucrar normas nacionales, regionales y locales simultáneamente.'
  ],['Identifica entidad territorial y materia.','Ubica instrumento de ordenamiento aplicable.','Revisa competencias concurrentes y determinantes superiores.','Analiza decisión concreta y su soporte.'],
  'Un municipio modifica el uso de un área sin revisar restricciones ambientales de superior jerarquía aplicables.','Contrastar la decisión local con el marco competencial y determinantes que jurídicamente condicionan el ordenamiento.',['Asumir que la autonomía municipal elimina cualquier restricción externa.','Concluir que los municipios nunca pueden decidir sobre uso del suelo.'],['ley-1454-2011','ley-388-1997','constitucion']),

  m(56,'Gestión pública, indicadores y control de gestión','Del objetivo institucional a evidencia de resultados.','Gestionar implica planear objetivos, ejecutar actividades, medir resultados y aprender para corregir. Un indicador debe tener definición, fuente, fórmula, periodicidad y responsable; interpretar porcentajes sin conocer denominador, cobertura o calidad de datos puede producir decisiones equivocadas.',[
    'Actividad, producto, resultado e impacto describen niveles distintos.','Cumplir 100 % de una meta mal definida no garantiza valor público.','Indicadores necesitan contexto temporal y comparadores pertinentes.'
  ],['Define objetivo y resultado esperado.','Diseña o interpreta indicador con fórmula y fuente.','Analiza desviación y causas.','Propone acción y verifica si mejora el resultado.'],
  'Una dependencia reporta 100 % de cumplimiento porque respondió 10 peticiones, pero recibió 25 en el periodo.','Revisar definición, denominador, universo y fuente antes de aceptar el indicador.',['Aceptar el 100 % porque así aparece en el tablero.','Concluir fraude sin revisar cómo fue calculado.'],['decreto-1499-2017','pgn-sgc','pgn-manual-calidad']),

  m(57,'Sistema de Gestión de Calidad y mejora continua','Procesos, PHVA, riesgos, no conformidades y acciones de mejora.','El sistema de gestión ordena procesos, responsabilidades, documentos, indicadores, riesgos y mecanismos de mejora. El ciclo PHVA ayuda a distinguir planear, ejecutar, verificar y actuar; una no conformidad debe analizarse para corregir el efecto y, cuando corresponda, abordar causas para reducir recurrencia.',[
    'Corregir un caso puntual no siempre elimina la causa que lo produjo.','Un procedimiento controlado necesita versión, responsable y acceso a la edición vigente.','Riesgo y no conformidad no son idénticos: uno mira incertidumbre futura y la otra un incumplimiento observado.'
  ],['Ubica proceso y requisito.','Describe evidencia objetiva del desvío.','Analiza causa y riesgo asociado.','Define acción, responsable, plazo y verificación de eficacia.'],
  'Un error de registro se repite cada semana y la única acción es corregir manualmente cada caso.','Analizar la causa sistémica y definir una acción que reduzca recurrencia, además de corregir los casos.',['Seguir corrigiendo individualmente sin estudiar la causa.','Eliminar el indicador para que el error deje de aparecer.'],['pgn-sgc','pgn-manual-calidad','decreto-1499-2017']),

  m(58,'Gestión documental y expediente','Ciclo documental, organización, conservación, TRD y expediente electrónico.','La gestión documental asegura autenticidad, integridad, disponibilidad, organización y disposición de los documentos institucionales durante su ciclo de vida. El expediente debe conservar orden y relaciones entre actuaciones; en entornos híbridos o electrónicos, los metadatos y controles de acceso son parte de la trazabilidad.',[
    'Guardar un archivo en una carpeta compartida no equivale a gestionarlo documentalmente.','Las Tablas de Retención Documental orientan permanencia y disposición según series/subseries.','Versiones y duplicados deben controlarse para evitar que una decisión use el documento equivocado.'
  ],['Clasifica documento y serie.','Registra e incorpora al expediente correcto.','Controla versiones, acceso y metadatos.','Aplica retención, transferencia o disposición según reglas.'],
  'Dos versiones de un informe circulan por correo y nadie sabe cuál fue incorporada formalmente al expediente.','Verificar registro, versión oficial y trazabilidad de incorporación antes de utilizarlo como soporte.',['Elegir la versión más reciente por fecha del archivo.','Guardar ambas con el mismo nombre y tratarlas como equivalentes.'],['ley-594-2000','pgn-manual-calidad','ley-527-1999']),

  m(59,'Atención, documentos de oficina e informes técnicos','Comunicar con claridad sin perder precisión ni trazabilidad.','El 3PU-15 debe atender usuarios, responder consultas y peticiones, producir proyectos y elaborar informes técnicos. Un documento institucional sólido identifica destinatario, propósito, hechos, fuentes, análisis, conclusión y responsable, usando lenguaje claro y diferenciando afirmación probada, inferencia y recomendación.',[
    'Lenguaje técnico innecesariamente complejo puede ocultar el razonamiento.','Un informe técnico debe mostrar método y límites, no solo una conclusión.','Datos personales o reservados deben minimizarse según necesidad del documento.'
  ],['Define propósito y audiencia.','Estructura hechos y fuentes.','Explica método, análisis y límites.','Revisa precisión, accesibilidad, reserva y versión final.'],
  'Un informe de 40 páginas concluye en una frase, sin explicar cómo se procesaron los datos ni qué archivos fueron usados.','Reestructurar el informe para hacer reproducible el análisis y rastreables las fuentes.',['Mantenerlo porque la extensión demuestra rigor.','Reducirlo a la conclusión sin anexos ni método.'],['pgn-convocatoria-104-v4','ley-1755-2015','ley-1712-2014','pgn-manual-calidad']),

  m(60,'Sistemas de información, calidad de datos y accesos','Datos confiables y permisos proporcionales al rol.','Los sistemas institucionales son fuentes de operación y evidencia, pero su contenido solo es útil si se conoce origen, calidad, reglas de actualización y responsables. Los accesos deben seguir necesidad funcional y mínimo privilegio; altas, cambios y retiros requieren trazabilidad para evitar cuentas huérfanas o permisos acumulados.',[
    'Exactitud, completitud, consistencia y oportunidad son dimensiones distintas de calidad.','El usuario lógico de un sistema no demuestra por sí solo quién estaba frente al equipo.','Un dato corregido debe conservar trazabilidad suficiente cuando forma parte de una actuación o registro institucional.'
  ],['Identifica fuente y dueño del dato.','Verifica reglas de captura y transformación.','Comprueba autorización y ciclo de vida de accesos.','Documenta cambios, excepciones y controles.'],
  'Una cuenta de un exfuncionario permanece activa y registra una consulta después de su retiro.','Preservar logs, verificar ciclo de vida de la cuenta y analizar quién pudo usarla sin asumir automáticamente autoría del exfuncionario.',['Atribuirle el evento al exfuncionario por el nombre de la cuenta.','Borrar la cuenta y sus registros inmediatamente para cerrar el riesgo.'],['pgn-convocatoria-104-v4','pgn-manual-calidad','ley-1581-2012']),

  m(61,'Logs, autenticación e identidad digital','Interpretar eventos técnicos sin convertirlos en personas automáticamente.','Un log registra eventos definidos por un sistema: autenticaciones, acciones, errores, cambios o accesos. Para interpretarlo se debe conocer formato, zona horaria, fuente, retención, sincronización y arquitectura. Usuario, IP, token o equipo son identificadores técnicos que requieren correlación para aproximarse a una atribución personal.',[
    'IP puede ser compartida, dinámica, NAT o VPN y no identifica por sí sola a una persona.','Una autenticación exitosa demuestra uso válido de una credencial según el sistema, no necesariamente presencia física del titular.','Relojes desincronizados pueden alterar una línea de tiempo si no se normalizan.'
  ],['Preserva log original y metadatos.','Documenta zona horaria, fuente y reglas de registro.','Correlaciona autenticación, dispositivo, red y acción.','Expresa nivel de atribución y explicaciones alternativas.'],
  'Un evento proviene de la IP asignada a una sede con cientos de usuarios y se propone identificar al responsable por esa dirección.','Correlacionar con DHCP/NAT/VPN, cuentas, equipos y otros registros antes de atribuir la acción.',['Identificar a la primera persona conectada a la sede.','Concluir que una IP nunca aporta información útil.'],['ley-527-1999','pgn-guia-pruebas','ley-1581-2012']),

  m(62,'Bases de datos como fuente probatoria','Estado actual, historial de cambios y cuentas de servicio.','Una consulta a una base de datos muestra un estado según el momento y la lógica de lectura; no necesariamente revela cómo llegó allí. Para investigar modificaciones se necesitan registros transaccionales, auditoría, backups, triggers, cuentas de aplicación o servicio y contexto de la arquitectura, evitando atribuir al usuario final acciones ejecutadas por procesos automáticos.',[
    'El valor actual de una fila no demuestra quién lo cambió.','Cuenta de base de datos puede representar una aplicación usada por muchas personas.','Backups y logs transaccionales pueden permitir reconstruir estados previos, pero su alcance depende de configuración y retención.'
  ],['Define dato y periodo de interés.','Preserva snapshot y fuentes de auditoría.','Relaciona usuario lógico, aplicación y flujo de negocio.','Reconstruye cambio y expresa límites de atribución.'],
  'La columna “updated_by” contiene siempre el usuario técnico de una aplicación y se usa para afirmar quién modificó cada registro.','Reconocer que ese campo identifica al proceso técnico y buscar trazas de sesión o negocio que permitan vincular la operación con un usuario final.',['Atribuir todas las modificaciones al administrador de la aplicación.','Descartar toda la base porque el campo no contiene personas.'],['pgn-guia-pruebas','ley-527-1999']),

  m(63,'Correo, archivos, metadatos y hash','Evidencia digital cotidiana y sus límites.','Correos y archivos combinan contenido visible con metadatos y registros del sistema. Fechas de creación o modificación pueden cambiar al copiar, descargar o convertir; cabeceras de correo aportan rutas y servidores, pero también necesitan contexto. El hash ayuda a demostrar que dos archivos tienen exactamente los mismos bytes, no quién los creó ni si su contenido es verdadero.',[
    'Nombre de archivo y fecha del explorador no bastan para reconstruir origen.','Reenviar un correo modifica su envoltura y puede perder información útil de cabeceras originales.','Hash debe calcularse y registrarse con algoritmo y momento de adquisición.'
  ],['Conserva mensaje/archivo en formato original disponible.','Extrae metadatos sin alterar innecesariamente la fuente.','Calcula integridad y registra herramientas.','Corrobora identidad, origen y contexto con otras fuentes.'],
  'Dos PDFs tienen el mismo nombre y apariencia, pero hashes diferentes.','Tratarlo como señal de que los bytes difieren y comparar contenido/metadatos para identificar la diferencia; no inferir por el hash cuál es auténtico.',['Declarar falso el de hash mayor.','Asumir que son idénticos porque se ven iguales.'],['ley-527-1999','pgn-guia-pruebas']),

  m(64,'Informe técnico informático','Del análisis reproducible a una conclusión útil para el expediente.','Un informe técnico debe responder una pregunta delimitada y permitir que otra persona competente entienda qué fuentes se recibieron, cómo se preservaron, qué herramientas y parámetros se usaron, qué resultados se obtuvieron y cuáles son sus limitaciones. La conclusión debe permanecer dentro de la competencia técnica y evitar calificaciones jurídicas no demostradas por el análisis.',[
    'Metodología reproducible vale más que una conclusión categórica sin soporte.','Anexos técnicos permiten mantener el cuerpo principal comprensible.','Una limitación explícita aumenta la confiabilidad cuando refleja honestamente el alcance del análisis.'
  ],['Formula objetivo y alcance.','Inventaría evidencias y verifica integridad.','Describe método, herramientas y resultados.','Concluye técnicamente y declara limitaciones.'],
  'Un análisis solo permite afirmar que una cuenta ejecutó una acción, pero no identificar físicamente a la persona que la usó.','Redactar esa distinción de forma explícita y recomendar correlaciones adicionales si son técnicamente posibles.',['Escribir que el titular de la cuenta realizó personalmente la acción.','Omitir el hallazgo porque no permite certeza absoluta sobre la persona.'],['pgn-convocatoria-104-v4','pgn-guia-pruebas','ley-527-1999']),

  m(65,'Word y elaboración profesional de documentos','Estructura, estilos, revisión, accesibilidad y control de cambios.','Word debe usarse como herramienta de estructuración y trazabilidad, no como máquina de espacios. Títulos, estilos, listas, tablas, referencias, comentarios y control de cambios permiten documentos consistentes y revisables; la versión final debe eliminar marcas no destinadas al receptor y conservar la trazabilidad interna que corresponda.',[
    'Enter y espacios repetidos producen documentos frágiles frente a estilos y conversiones.','Control de cambios permite distinguir propuesta, aceptación y autor de modificaciones.','Encabezados semánticos y texto alternativo mejoran accesibilidad.'
  ],['Define estructura y estilos.','Redacta contenido antes de microformatear.','Usa revisión/control de cambios de forma consciente.','Genera versión final limpia y conserva versión de trabajo según gestión documental.'],
  'Un informe de 60 páginas tiene títulos hechos manualmente con negrilla y tamaño, sin estilos ni tabla automática.','Normalizar estilos y estructura para facilitar navegación, actualización y accesibilidad sin alterar el contenido sustancial.',['Añadir más espacios para alinear visualmente.','Convertir todo en una imagen para que no cambie el formato.'],['pgn-convocatoria-104-v4','ley-594-2000']),

  m(66,'Excel para información institucional','Datos tabulares, tipos, referencias, filtros, validación y tablas dinámicas.','Excel es útil para organizar y explorar información si cada fila representa una observación y cada columna una variable consistente. Mezclar formatos, celdas combinadas, subtotales manuales y tipos incompatibles dificulta análisis; fórmulas y tablas dinámicas deben conservar posibilidad de volver al detalle original.',[
    'Ordenar cambia la presentación; filtrar restringe temporalmente qué filas se muestran.','Texto que parece fecha o número puede comportarse distinto en fórmulas.','Una tabla dinámica resume datos, pero no corrige errores de la fuente.'
  ],['Conserva una tabla fuente limpia.','Valida tipos, faltantes y duplicados.','Aplica fórmulas/filtros sin borrar registros.','Resume y vuelve al detalle para verificar conclusiones.'],
  'Una base tiene identificaciones repetidas porque cada persona puede tener varias actuaciones y alguien elimina todos los “duplicados” por documento.','Definir primero la unidad de análisis y la clave legítima antes de eliminar registros.',['Usar “Quitar duplicados” solo sobre identificación.','Contar todas las filas como personas distintas.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-concurso-2026']),

  m(67,'Análisis de datos para decidir','Frecuencias, tendencia central, dispersión, denominadores y sesgo.','Analizar datos implica preguntar de dónde vienen, qué representan y qué población dejan fuera antes de calcular. Media, mediana, porcentajes y tasas responden preguntas diferentes; la dispersión y los valores atípicos ayudan a evitar promedios engañosos, y toda comparación porcentual necesita un denominador consistente.',[
    'Media puede distorsionarse por valores extremos.','Porcentaje sin universo o denominador es una cifra incompleta.','Correlación entre dos variables no prueba que una cause la otra.'
  ],['Define población y unidad de análisis.','Revisa calidad, faltantes y sesgos.','Escoge medida adecuada.','Interpreta con contexto y comunica incertidumbre.'],
  'Dos regionales tienen 20 quejas cada una, pero una atiende 2.000 casos y la otra 100.','Comparar también tasas o proporciones según el universo, no solo conteos absolutos.',['Concluir que son iguales porque tienen 20.','Concluir que la regional grande es peor porque maneja más casos totales.'],['pgn-convocatoria-104-v4','pgn-sgc']),

  m(68,'Metodología de investigación aplicada','Pregunta, hipótesis, fuente, triangulación y sesgo de confirmación.','Investigar profesionalmente exige formular una pregunta resoluble, definir qué evidencia podría cambiar la conclusión y buscar activamente información que confirme o contradiga la hipótesis. Triangular significa contrastar fuentes o métodos con independencia suficiente, no repetir la misma afirmación en varios documentos.',[
    'Pregunta demasiado amplia produce recolección indiscriminada.','Hipótesis no es conclusión; es una explicación provisional sometida a prueba.','Sesgo de confirmación aparece cuando solo buscamos datos compatibles con la primera explicación.'
  ],['Formula pregunta concreta.','Plantea hipótesis y alternativas.','Selecciona fuentes independientes.','Contrasta, actualiza y documenta conclusión provisional.'],
  'Los primeros dos documentos sugieren negligencia y el equipo decide dejar de buscar evidencia contraria.','Mantener búsqueda equilibrada y probar hipótesis alternativas antes de concluir.',['Cerrar el análisis porque dos fuentes coinciden.','Cambiar la conclusión por la hipótesis contraria sin obtener nueva evidencia.'],['pgn-convocatoria-104-v4','pgn-guia-investigacion']),

  m(69,'Síntesis crítica y resolución de inconsistencias','Diferenciar dato, hecho, inferencia y conclusión.','Los expedientes reales suelen contener datos incompatibles entre sistemas, documentos o testimonios. La solución no es escoger arbitrariamente una fuente, sino identificar qué representa cada dato, cuándo se generó, qué proceso lo transforma y cuál es su fiabilidad para la pregunta concreta. Una conclusión sólida muestra también las inconsistencias que permanecen abiertas.',[
    'Dos fuentes pueden ser correctas y referirse a momentos o definiciones distintas.','Una inconsistencia es una señal para investigar, no automáticamente un fraude.','La síntesis debe preservar trazabilidad desde la conclusión hasta las fuentes.'
  ],['Lista afirmaciones relevantes.','Asocia cada una a fuente y fecha.','Explica contradicciones y posibles causas.','Concluye solo hasta donde llega la evidencia.'],
  'El sistema A registra un trámite “cerrado” y el sistema B “activo”, pero usan definiciones distintas de cierre.','Reconstruir la semántica y el momento de actualización de cada sistema antes de declarar inconsistencia material.',['Asumir que uno de los sistemas es falso.','Escoger el dato que aparezca en el sistema más nuevo.'],['pgn-convocatoria-104-v4','pgn-manual-calidad']),

  m(70,'Responsabilidad con la Organización y Organización del Trabajo · Nivel B','Compromiso institucional, priorización y orden bajo reglas.','Las competencias comportamentales no se responden como preguntas jurídicas de una única conducta perfecta. Responsabilidad con la organización y organización del trabajo observan comportamientos consistentes con compromiso, cumplimiento, cuidado de recursos, planificación, priorización y seguimiento, dentro del nivel esperado por el perfil.',[
    'Cumplir metas no justifica vulnerar procedimiento.','Organizar no significa rigidez absoluta frente a cambios justificados.','Responsabilidad incluye alertar riesgos y asumir efectos de las propias decisiones.'
  ],['Comprende la conducta observable.','Lee el contexto completo.','Busca consistencia entre prioridad, regla y resultado.','Evita fabricar un personaje siempre extremo o socialmente ideal.'],
  'Tienes dos entregas simultáneas, una urgente y otra importante, y detectas que no podrás cumplir ambas con calidad.','Priorizar con criterios objetivos, comunicar oportunamente el riesgo y reorganizar el trabajo dentro de los parámetros institucionales.',['Ocultar el retraso hasta el último momento.','Trabajar ambas sin priorización aunque aumente el riesgo de errores.'],['pgn-convocatoria-104-v4','pgn-diccionario-competencias']),

  m(71,'Investigación · Nivel B y Pensamiento Conceptual · Nivel A','Buscar evidencia y construir relaciones útiles entre hechos.','Investigación Nivel B apunta a obtener y verificar información de manera estructurada y suficiente para resolver problemas. Pensamiento conceptual Nivel A implica reconocer patrones, relaciones y conceptos que permiten comprender situaciones sin inventar complejidad. En prueba comportamental importa la tendencia conductual, no recitar definiciones.',[
    'Investigar no es acumular datos sin criterio.','Pensar conceptualmente ayuda a encontrar el patrón común entre casos diferentes.','Una inferencia debe sostenerse en información suficiente y poder revisarse frente a nueva evidencia.'
  ],['Aclara qué necesitas saber.','Busca información confiable y contrastada.','Organiza patrones y relaciones.','Actualiza la comprensión cuando cambian los datos.'],
  'Tres expedientes muestran errores semejantes y debes identificar si existe una causa común.','Comparar variables relevantes, verificar datos y construir una hipótesis de patrón antes de proponer conclusiones.',['Asumir que el mismo funcionario es responsable en todos.','Tratar cada expediente como aislado y evitar cualquier comparación.'],['pgn-convocatoria-104-v4','pgn-diccionario-competencias']),

  m(72,'Orientación a Resultados · Nivel A y Cumplimiento de Parámetros · Nivel B','Lograr objetivos sin perder calidad, legalidad ni estándar institucional.','Orientación a resultados implica dirigir esfuerzos hacia objetivos verificables; cumplimiento de parámetros exige respetar estándares, procedimientos y criterios de calidad. Las dos competencias se complementan: un resultado obtenido saltándose controles puede ser funcionalmente incorrecto, y seguir un procedimiento sin comprender el resultado esperado puede volverse ritualista.',[
    'Resultado debe ser legítimo, no solo rápido.','Parámetro de trabajo puede incluir calidad, seguridad, plazo y trazabilidad.','Ante una regla ambigua se busca aclaración o escalamiento, no improvisación silenciosa.'
  ],['Define resultado y estándar.','Planifica con indicadores claros.','Controla calidad durante la ejecución.','Corrige desviaciones y documenta excepciones autorizadas.'],
  'Para cumplir una meta mensual alguien propone registrar como terminados casos que aún esperan verificación final.','Mantener el estándar de cierre y gestionar la meta con información real, explicando la desviación si existe.',['Cambiar el estado para mostrar cumplimiento.','Dejar de medir el indicador.'],['pgn-convocatoria-104-v4','pgn-diccionario-competencias']),

  m(73,'Cómo abordar la prueba comportamental','Consistencia, contexto y afirmaciones directas o inversas.','Las pruebas comportamentales buscan patrones de respuesta asociados al perfil, no el dominio de una norma. Intentar identificar siempre la opción “más bonita” puede producir contradicciones. Es mejor comprender cada competencia y responder de forma honesta y consistente con conductas laborales sostenibles.',[
    'Una afirmación inversa puede expresar la misma competencia desde una conducta no deseada.','Responder siempre extremos por estrategia puede crear perfiles incoherentes.','Contexto laboral importa: colaboración no significa ceder ante conductas contrarias a reglas.'
  ],['Lee literalmente la conducta.','Identifica competencia y dirección de la afirmación.','Piensa en tu comportamiento habitual, no en una escena ideal.','Revisa coherencia global sin manipular cada respuesta.'],
  'Una afirmación dice “cuando encuentro un error prefiero ocultarlo para evitar problemas con el equipo”.','Reconocer que la conducta compromete responsabilidad y parámetros de trabajo, sin reinterpretarla como lealtad al equipo.',['Valorarla positivamente porque evita conflicto.','Responder siempre la opción más extrema sin leer el resto de la escala.'],['pgn-convocatoria-104-v4','pgn-diccionario-competencias']),

  m(74,'Método C-E-P-P-A para casos integrales','Competencia → Etapa → Problema → Prueba → Actuación.','Los casos complejos se vuelven manejables si se resuelven en orden. Primero se determina quién puede actuar; luego en qué etapa está el asunto; después cuál es el problema jurídico o técnico; qué evidencia existe o falta; y finalmente cuál actuación corresponde. Saltar directamente a una figura jurídica conocida es una fuente frecuente de errores.',[
    'Una opción puede mencionar una institución real y ser incorrecta por etapa.','Antes de decidir conviene identificar qué hecho, si cambiara, alteraría la respuesta.','La mejor respuesta suele preservar competencia, garantías, evidencia y secuencia simultáneamente.'
  ],['Competencia: quién tiene atribución.','Etapa: qué actuaciones son oportunas ahora.','Problema y prueba: qué debe resolverse y con qué soporte.','Actuación: escoge la medida procedente y proporcional.'],
  'Hay una queja, el posible autor aún no está individualizado y una opción propone formular cargos de inmediato.','Aplicar C-E-P-P-A: reconocer la etapa y la falta de individualización antes de escoger la actuación prevista para ese supuesto.',['Elegir cargos porque es la medida más fuerte.','Archivar automáticamente porque aún no hay autor identificado.'],['ley-1952-2019','pgn-guia-disciplinaria','pgn-convocatoria-104-v4']),

  m(75,'Ruta condicional · Economía y Hacienda Pública','Por qué existe y cuándo priorizarla.','La convocatoria incorpora conocimientos adicionales para la Procuraduría Delegada para la Economía y la Hacienda Pública. Esta ruta se mantiene separada del núcleo común porque su prioridad real depende de la asignación, especialidad y futuras orientaciones oficiales de prueba. Su objetivo es brindar bases suficientes sin desplazar instrucción, probatorio y preventivo.',[
    'Un contenido condicional no debe confundirse con conocimiento común obligatorio para todos los escenarios.','Hacienda pública estudia obtención, asignación y uso de recursos públicos.','Economía y contabilidad aportan lenguaje para comprender información financiera y presupuestal.'
  ],['Domina primero núcleo común.','Identifica si la especialidad resulta aplicable.','Estudia fundamentos económico-financieros.','Integra conceptos a casos preventivos o disciplinarios sin invadir experticias ajenas.'],
  'Una futura guía oficial confirma que todos los inscritos deben responder un bloque de Hacienda Pública.','Elevar esta ruta de condicional a prioritaria y ajustar plan de estudio sin borrar progreso previo.',['Ignorar la guía porque el currículo ya estaba cerrado.','Reemplazar todo el núcleo disciplinario por economía.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-concurso-2026']),

  m(76,'Derecho tributario, económico y financiero · fundamentos','Lenguaje mínimo para comprender decisiones y riesgos económicos.','Esta ruta introduce conceptos de obligación tributaria, ingresos, gasto, financiación, mercados y regulación únicamente al nivel necesario para interpretar expedientes o actuaciones vinculadas a la especialidad de Economía y Hacienda Pública. No pretende convertir al estudiante en tributarista o economista profesional.',[
    'Ingreso público, gasto público y deuda responden a decisiones jurídicas y económicas distintas.','Un indicador financiero necesita periodo, unidad y fuente.','Incumplimiento tributario, mala gestión y corrupción son categorías diferentes que requieren prueba propia.'
  ],['Identifica concepto económico o financiero.','Ubica actor y norma relevante.','Comprueba datos y periodo.','Conecta hallazgo con competencia PGN sin saltar a responsabilidad.'],
  'Un indicador de recaudo cae y se propone concluir que existió corrupción en la administración tributaria.','Analizar causas económicas, administrativas y normativas antes de formular una hipótesis disciplinaria específica.',['Tratar toda caída del recaudo como corrupción.','Ignorar el indicador porque no prueba por sí solo una falta.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-concurso-2026']),

  m(77,'Hacienda y contabilidad pública · lectura básica','Presupuesto, ejecución y estados como fuentes de información pública.','La información presupuestal y contable ayuda a verificar cómo se programan, comprometen, obligan y pagan recursos y cómo se reconocen hechos económicos. Para una actuación de control, el objetivo es comprender la trazabilidad básica y detectar preguntas que requieran profundización, no asumir que cualquier diferencia numérica es irregular.',[
    'Apropiación, compromiso, obligación y pago representan momentos distintos.','Saldo contable y disponibilidad presupuestal no son sinónimos.','Conciliar fuentes permite identificar diferencias de corte, registro o criterio antes de hablar de error.'
  ],['Define el concepto y periodo.','Relaciona documento con etapa presupuestal/contable.','Cruza fuentes y explica diferencias.','Escala al experto cuando la conclusión exige conocimiento especializado.'],
  'Un tablero muestra ejecución presupuestal alta, pero pagos bajos al mismo corte.','Distinguir compromiso/obligación/pago y revisar cronología antes de concluir incumplimiento o pérdida de recursos.',['Asumir que todo recurso no pagado fue desviado.','Tratar ejecución y pago como el mismo indicador.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-concurso-2026']),

  m(78,'Ruta condicional · Fuerza Pública, DD. HH. y DIH','Bases para una especialidad con régimen y contexto propios.','La convocatoria lista, para la Delegada para la Fuerza Pública, régimen disciplinario de Fuerzas Militares y Policía, normas internas, control de armas, municiones y explosivos, Derechos Humanos y Derecho Internacional Humanitario. Es una ruta condicional que requiere especial cuidado porque coexisten regímenes especiales y obligaciones reforzadas.',[
    'No debe aplicarse automáticamente el régimen general cuando existe una regla especial válida.','Derechos Humanos y DIH tienen ámbitos y fuentes que deben distinguirse.','Información operativa sensible puede exigir controles adicionales de acceso y manejo.'
  ],['Identifica sujeto y régimen especial.','Ubica contexto de paz/conflicto y norma aplicable.','Distingue responsabilidad disciplinaria de otras responsabilidades.','Preserva garantías y manejo seguro de información.'],
  'Un caso involucra a un miembro de la Fuerza Pública y alguien aplica sin revisión una regla disciplinaria general.','Identificar primero el régimen aplicable al sujeto y la conducta, así como la competencia, antes de seleccionar la norma.',['Aplicar siempre el régimen general porque es más conocido.','Asumir que la PGN nunca puede intervenir en asuntos de Fuerza Pública.'],['pgn-convocatoria-104-v4','constitucion','pgn-buenas-practicas-ddhh']),

  m(79,'Currículo vivo y especializaciones','Cómo adaptar el curso cuando aparezcan nuevas orientaciones oficiales.','La convocatoria define hoy funciones, conocimientos y competencias, pero una guía de orientación específica puede precisar núcleos, distribución, formato o énfasis. Umbral conserva un núcleo común sólido y marca explícitamente lo condicional para poder subir o bajar prioridades sin reescribir tu historial de aprendizaje.',[
    'Actualizar prioridad no significa que lo aprendido antes deje de servir.','La fuente más específica y vigente debe prevalecer sobre inferencias pedagógicas anteriores.','Toda expansión futura debe mapearse contra funciones, conocimiento oficial y habilidades evaluables antes de publicarse.'
  ],['Detecta nueva fuente oficial.','Compara contra matriz de cobertura.','Clasifica cambios en obligatorio, complementario o condicional.','Versiona contenido manteniendo progreso y dejando trazabilidad.'],
  'Se publica una guía oficial que elimina un tema inferido y añade otro no previsto.','Versionar el mapa: reducir el tema inferido y añadir el nuevo eje con fuentes y práctica, conservando progreso histórico.',['Ignorar la guía para no cambiar el curso.','Borrar el progreso completo y reconstruir desde cero.'],['pgn-convocatoria-104-v4','pgn-res-076-2026','pgn-res-108-2026','pgn-res-133-2026','pgn-manual-v9','pgn-concurso-2026']),

  m(80,'Arquitectura de sistemas e información','Cómo se conectan procesos, aplicaciones, datos e infraestructura.','Un sistema de información no es solo una aplicación: combina procesos, personas, datos, reglas, integraciones e infraestructura. Para analizarlo profesionalmente debes distinguir arquitectura lógica y física, dependencias, interfaces, fuentes maestras, flujos de información y puntos de control; en el sector público, la tecnología debe alinearse con misión, servicios y generación de valor público.',[
    'Una falla visible en la interfaz puede originarse en datos, integración, red, autenticación o lógica de negocio.','Arquitectura empresarial conecta objetivos institucionales, procesos, información y tecnología.','Documentar dependencias e interfaces permite explicar impacto, riesgo y trazabilidad de un cambio.'
  ],['Define el servicio o proceso soportado.','Dibuja componentes, datos e integraciones relevantes.','Identifica dependencias, controles y puntos únicos de falla.','Relaciona el hallazgo técnico con impacto institucional sin exceder la evidencia.'],
  'Un sistema deja de mostrar expedientes recientes y el equipo atribuye el problema de inmediato a la base de datos.','Reconstruir el flujo completo: captura, integración, reglas, servicios, base de datos, permisos y presentación antes de atribuir causa.',['Reiniciar la base de datos sin preservar evidencia ni revisar dependencias.','Concluir que el usuario cometió un error porque la interfaz no muestra información.'],['pgn-convocatoria-104-v4','pgn-manual-v9','mintic-mrae-v3']),

  m(81,'Redes y comunicaciones para investigación técnica','TCP/IP, DNS, NAT, VPN, puertos y trazabilidad de conexiones.','Comprender redes ayuda a interpretar registros técnicos sin convertir una dirección IP en una identidad personal. Debes reconocer capas básicas de comunicación, direccionamiento, DNS, traducción de direcciones, VPN, proxies, puertos, sesiones y sincronización temporal para correlacionar eventos con prudencia.',[
    'Una IP pública puede representar múltiples equipos o usuarios detrás de NAT o proxy.','DNS resuelve nombres; no demuestra por sí mismo quién realizó una acción.','La hora de un evento depende de zona horaria, sincronización y fuente del registro.'
  ],['Identifica origen y destino del evento.','Ubica NAT, VPN, proxy o infraestructura intermedia.','Correlaciona puertos, sesiones, dispositivos y tiempos.','Expresa la atribución como hipótesis técnica con límites documentados.'],
  'Un registro de aplicación muestra una IP pública compartida por toda una sede y se pide identificar al funcionario responsable.','Correlacionar la IP con NAT/VPN, logs de autenticación, dispositivo, horario y otros registros antes de aproximarse a una atribución.',['Asignar responsabilidad al titular del enlace de internet.','Descartar el dato porque una IP compartida nunca aporta información útil.'],['pgn-convocatoria-104-v4','pgn-manual-v9','mintic-mspi-2025']),

  m(82,'Seguridad de la información y ciberseguridad','Confidencialidad, integridad, disponibilidad, riesgo, controles e incidentes.','La seguridad de la información busca preservar confidencialidad, integridad, disponibilidad y privacidad mediante gestión de riesgos y controles. En una entidad pública debes distinguir activo, amenaza, vulnerabilidad, riesgo, evento e incidente; también separar prevención, detección, respuesta, recuperación y preservación de evidencia.',[
    'Vulnerabilidad no es incidente: es una debilidad que puede ser explotada.','Un control reduce riesgo, pero no garantiza riesgo cero.','Responder a un incidente debe contener el daño sin destruir registros necesarios para análisis posterior.'
  ],['Identifica activo y objetivo de seguridad.','Formula amenaza, vulnerabilidad e impacto.','Evalúa controles existentes y evidencia del evento.','Contén, preserva, recupera y documenta según competencia.'],
  'Se detecta actividad anómala en una cuenta privilegiada y alguien propone formatear de inmediato el equipo para “limpiarlo”.','Contener el riesgo preservando logs y evidencia relevante, documentar acciones y coordinar respuesta antes de destruir información potencialmente útil.',['Formatear primero y documentar después.','No hacer nada hasta demostrar con certeza quién atacó.'],['pgn-convocatoria-104-v4','pgn-manual-v9','mintic-mspi-2025']),

  m(83,'Ingeniería de software y ciclo de cambio','Requisitos, diseño, desarrollo, pruebas, despliegue, versiones y control de cambios.','Un cambio de software confiable necesita trazabilidad desde la necesidad hasta la versión desplegada. Requisitos, código, revisión, pruebas, aprobación, despliegue y rollback generan evidencia útil para explicar qué cambió, quién autorizó, qué controles se aplicaron y por qué un defecto llegó o no a producción.',[
    'Un commit identifica una operación en un repositorio, no necesariamente toda la autoría material o la autorización del cambio.','Pruebas unitarias, integración y aceptación cubren riesgos distintos.','Separar desarrollo, aprobación y despliegue reduce conflictos y mejora trazabilidad.'
  ],['Reconstruye requisito y ticket de cambio.','Relaciona versión, commits, revisiones y pruebas.','Verifica aprobación, despliegue y configuración efectiva.','Distingue defecto, cambio autorizado, bypass de control y efecto real.'],
  'Producción contiene una validación que no aparece en la rama principal y se sospecha una modificación irregular.','Comparar artefacto desplegado, repositorio, pipeline, aprobaciones, logs y configuración para reconstruir el cambio antes de atribuirlo.',['Culpar al último desarrollador que hizo commit.','Asumir que si el repositorio está correcto producción también lo está.'],['pgn-convocatoria-104-v4','pgn-manual-v9','mintic-mrae-v3','mintic-mspi-2025']),

  m(84,'Gobierno de datos y bases de datos · fundamentos profesionales','Modelo relacional, transacciones, integridad, auditoría, respaldos y calidad.','Las bases de datos sostienen decisiones institucionales y requieren gobierno: definición de datos, responsables, reglas de calidad, integridad, seguridad, retención y trazabilidad. Debes comprender claves, relaciones, transacciones, restricciones, vistas, procedimientos, auditoría y respaldos para diferenciar un dato incorrecto, una transformación legítima y una alteración no explicada.',[
    'El estado actual de una tabla no reconstruye por sí solo el historial de cambios.','Integridad referencial evita ciertas inconsistencias, pero no garantiza que el dato represente la realidad.','Backups, logs transaccionales y auditoría tienen propósitos distintos y deben correlacionarse con la aplicación.'
  ],['Define entidad, clave y regla de negocio relevante.','Verifica origen, transacción y controles de integridad.','Busca auditoría, historial, respaldos y procesos automáticos relacionados.','Documenta calidad, cambio observado y límites de atribución.'],
  'Un registro crítico aparece con un valor distinto al del día anterior y la aplicación usa una cuenta de servicio compartida.','Reconstruir transacciones, auditoría, jobs, aplicación y accesos privilegiados antes de atribuir el cambio a un usuario final.',['Atribuirlo al dueño funcional del registro.','Restaurar el backup inmediatamente sin preservar el estado actual.'],['pgn-convocatoria-104-v4','pgn-manual-v9','mintic-mrae-v3','mintic-mspi-2025']),

]
